  /// หน้า Order Set ใน workflow (Figma 330-2): การ์ดใหญ่เลือกชุด · ที่ใช้บ่อย · ชุดทั้งหมด
  /// การติ๊กรายการจริงอยู่ในหน้าย่อยของ stepper (ยา / Lab / X-ray / หัตถการ)
  /// ขั้นสั่งการรักษา (Figma 331-350): เลือกชุด standing order + ลำดับคำสั่งที่หยิบมา
  /// ใบคำสั่งแสดงในแท็บคำสั่งแพทย์ฝั่งซ้าย แตะรายการที่นั่นเพื่อหยิบมาเรียงที่นี่
  List<Widget> _orderSetPage() {
    // เข้าขั้นนี้: สลับแผงซ้ายไปแท็บคำสั่งแพทย์ (ใบคำสั่งให้หยิบ) ครั้งเดียวต่อการเข้า
    if (_detailTab != 3 && _soTabAuto != _caseP().hn) {
      _soTabAuto = _caseP().hn;
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (mounted) setState(() => _detailTab = 3);
      });
    }
    if (_soPickOpen) return [_soPickPage()];
    // เคสที่ยังไม่เคยสั่ง: ล้างใบติ๊กตัวอย่างที่ค้างจากเคสอื่นก่อนเริ่ม
    if (!_soStarted && (_orderPicked.isNotEmpty || _soPnPick.isNotEmpty)) {
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (!mounted) return;
        setState(() {
          _orderPicked.clear();
          _soPnPick.clear();
          _soTick.clear();
        });
      });
    }
    // หน้า Order Set (การ์ดใหญ่ · ที่ใช้บ่อย · ตารางทุกชุด)
    // ใบคำสั่งอยู่แผงซ้าย แตะติ๊กรายการที่นั่น
    return _orderSetGrid();
  }

  /// หน้าย่อยเลือกชุดเปิดอยู่ (หัวแผง = breadcrumb · footer ย้อนกลับ)
  bool get _soPickNested =>
      (_soPickOpen || _soEdit != null) &&
      _speechOpen &&
      _steps[_speechStep].$2 == 'สั่งการรักษา';

  void _soPickEnter() {
    HapticFeedback.selectionClick();
    setState(() {
      _formFwd = true;
      _soPickOpen = true;
    });
  }

  void _soPickClose() {
    _ftCommit?.call();
    _soPickCloseNow();
  }

  void _soPickCloseNow() => setState(() {
        _formFwd = false;
        _soPickOpen = false;
        _soPickFocus = false;
        _soEdit = null;
      });

  /// หัวหน้าย่อย: ปุ่มกลับติดบนสุด + ชื่อหน้า (แทน breadcrumb)
  Widget _soPickCrumb() => _soEditItem != null
      ? _soEditCrumb(_soEditItem!)
      : Padding(
          padding: const EdgeInsets.fromLTRB(20.0, 10.0, 16.0, 6.0),
          child: Row(children: [
            _CrumbPrev('Standing Order', onTap: _soPickClose),
            const _CrumbSep(),
            Expanded(
              child: Text('เทมเพลต',
                  maxLines: 1,
                  overflow: TextOverflow.ellipsis,
                  style: _t(14.0, color: _inkTitle, weight: FontWeight.w600)),
            ),
          ]),
        );

  /// ข้อมูลเคสที่ใช้วิเคราะห์ (ค่าจริง) สำหรับแสดงระหว่างวิเคราะห์
  List<String> _soRecReads() {
    final c = _case;
    final p = _caseP();
    String n(double v) =>
        v % 1 == 0 ? v.toStringAsFixed(0) : v.toStringAsFixed(1);
    return [
      'ประเภทผู้ป่วย ${p.type?.label ?? 'ยังไม่ระบุ'}  อาการสำคัญ ${c.cc}',
      [
        if (c.hr.isNotEmpty) 'HR ${n(c.hr.last)}',
        if (c.sbp.isNotEmpty && c.dbp.isNotEmpty)
          'BP ${n(c.sbp.last)}/${n(c.dbp.last)}',
        if (c.rr.isNotEmpty) 'RR ${n(c.rr.last)}',
        if (c.bt.isNotEmpty) 'BT ${n(c.bt.last)}',
        if (c.spo2.isNotEmpty) 'SpO₂ ${n(c.spo2.last)}',
        if (c.gcs != null)
          'GCS ${RegExp(r'E\d').stringMatch(c.gcs!) ?? ''}'
              '${RegExp(r'V\d').stringMatch(c.gcs!) ?? ''}'
              '${RegExp(r'M\d').stringMatch(c.gcs!) ?? ''}',
      ].join('  '),
      'เทียบกับ Standing Order ทั้งหมดในโรงพยาบาล',
    ];
  }

  /// ชุดที่แนะนำจากข้อมูลจริงของเคส: ให้คะแนนทุกชุดจากประเภทผู้ป่วย อาการสำคัญ/HPI
  /// สัญญาณชีพล่าสุด (เกณฑ์ SIRS/qSOFA) ผลแล็บ และคำวินิจฉัย · คืน (ชุด, เหตุผลที่มีค่าจริง)
  /// คะแนนสูงสุดต่ำกว่า 2 = ไม่แนะนำ (ไม่เดา P1)
  (String, String)? _soRecommend() {
    final c = _case;
    final p = _caseP();
    final text = '${c.cc} ${c.hpi} ${c.dx.map((d) => d.text).join(' ')}';
    bool has(List<String> ws) => ws.any(text.contains);
    String n(double v) =>
        v % 1 == 0 ? v.toStringAsFixed(0) : v.toStringAsFixed(1);
    double? last(List<double> xs) => xs.isEmpty ? null : xs.last;
    final hr = last(c.hr), sbp = last(c.sbp), rr = last(c.rr), bt = last(c.bt);
    ErLab? lab(String k) =>
        c.labs.where((l) => l.name.toLowerCase().contains(k)).firstOrNull;
    final score = <String, int>{};
    final why = <String, List<String>>{};
    void add(String set, int pt, String r) {
      score[set] = (score[set] ?? 0) + pt;
      (why[set] ??= []).add(r);
    }

    switch (p.type) {
      case _Ptype.sepsis:
        add('Sepsis', 3, 'ประเภทผู้ป่วย Sepsis');
      case _Ptype.trauma:
        add('Trauma', 3, 'ประเภทผู้ป่วย Trauma');
      case _Ptype.stemi:
        add('Chest Pain', 3, 'ประเภทผู้ป่วย STEMI');
      case _Ptype.stroke:
        add('Stroke Fast Tract', 3, 'ประเภทผู้ป่วย Stroke');
      case null:
        break;
    }
    // Sepsis: SIRS / qSOFA จากสัญญาณชีพล่าสุด + lactate
    if (bt != null && (bt >= 38.0 || bt < 36.0))
      add('Sepsis', 1, 'BT ${n(bt)}');
    if (hr != null && hr > 90) add('Sepsis', 1, 'HR ${n(hr)}');
    if (rr != null && rr >= 22) add('Sepsis', 1, 'RR ${n(rr)}');
    if (sbp != null && sbp <= 100) add('Sepsis', 1, 'SBP ${n(sbp)}');
    if (lab('lactate') case final l? when l.value > 2) {
      add('Sepsis', 2, 'Lactate ${n(l.value)}');
    }
    if (has(const ['ไข้', 'ติดเชื้อ', 'sepsis']))
      add('Sepsis', 1, 'มีไข้/ติดเชื้อ');
    // Trauma
    if (has(const [
      'ล้ม',
      'ชน',
      'อุบัติเหตุ',
      'บาดแผล',
      'บาดเจ็บ',
      'กระแทก',
      'ตก',
      'พลิก',
      'ผิดท่า',
      'เคล็ด',
      'หัก',
      'บวม',
    ])) {
      add('Trauma', 2, 'กลไกบาดเจ็บในอาการสำคัญ');
    }
    // Chest pain
    if (has(const ['เจ็บหน้าอก', 'แน่นหน้าอก']))
      add('Chest Pain', 2, 'เจ็บแน่นหน้าอก');
    if (lab('trop') case final l? when l.value > l.hi && l.hi > 0) {
      add('Chest Pain', 2, 'Troponin ${n(l.value)}');
    }
    // Stroke
    if (has(const ['อ่อนแรง', 'ปากเบี้ยว', 'พูดไม่ชัด'])) {
      add('Stroke Fast Tract', 2, 'อาการทางระบบประสาท');
    }
    // Appendicitis
    if (has(const ['ท้องขวาล่าง', 'ไส้ติ่ง']))
      add('Appendicitis', 3, 'ปวดท้องขวาล่าง');
    // Snake bite
    if (has(const ['งู'])) add('งูกัด', 4, 'ถูกงูกัด');

    if (score.isEmpty) return null;
    final best = score.entries.reduce((a, b) => b.value > a.value ? b : a);
    if (best.value < 2) return null;
    return (best.key, why[best.key]!.take(3).join('  '));
  }

  /// หน้าย่อยเลือกชุด: รายการทุกชุดในการ์ดขาว (แถวแบบรายการวินิจฉัย) แตะ = ใช้ชุดนั้นแล้วกลับ
  /// กด "AI แนะนำ": จังหวะวิเคราะห์ (อ่านประเภทผู้ป่วย → อาการสำคัญ → จับคู่ชุด) แล้วค่อยแสดงชุด
  void _soRecAsk() {
    final hn = _caseP().hn;
    if (_soRecBusy.contains(hn)) return;
    HapticFeedback.selectionClick();
    setState(() {
      _soRecAsked.remove(hn);
      _soRecBusy.add(hn);
      _soRecStep = 0;
    });
    for (final (i, ms) in const [(1, 1100), (2, 2200)]) {
      Future.delayed(Duration(milliseconds: ms), () {
        if (mounted && _soRecBusy.contains(hn)) setState(() => _soRecStep = i);
      });
    }
    Future.delayed(const Duration(milliseconds: 3200), () {
      if (!mounted) return;
      HapticFeedback.lightImpact();
      setState(() {
        _soRecBusy.remove(hn);
        _soRecAsked.add(hn);
      });
    });
  }

  /// การ์ดระหว่างวิเคราะห์: พื้นไล่สี AI · วงหมุน + "AI กำลังวิเคราะห์" · ขั้นตอนติ๊กทีละขั้น · skeleton shimmer
  Widget _soRecBusyCard() {
    final steps = _soRecReads();
    return Container(
      padding: const EdgeInsets.fromLTRB(14.0, 14.0, 14.0, 16.0),
      decoration: BoxDecoration(
        gradient: const LinearGradient(
          begin: Alignment.centerLeft,
          end: Alignment.centerRight,
          colors: [Color(0xFFE6EEFD), Color(0xFFF1ECFC), Colors.white],
          stops: [0.0, 0.55, 1.0],
        ),
        borderRadius: BorderRadius.circular(20.0),
      ),
      child: Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
        // ไอคอนหมวดคำสั่ง (ยา Lab X-ray หัตถการ อื่น ๆ) โคจรรอบดาว AI แล้วรวมเข้ากลาง
        const SizedBox(height: 150.0, child: _SoOrbit()),
        const SizedBox(height: 6.0),
        Center(
          child: Text('AI กำลังวิเคราะห์ข้อมูลเคส',
              style: _t(14.0, color: _inkTitle, weight: FontWeight.w700)),
        ),
        const SizedBox(height: 4.0),
        Center(
          child: AnimatedSwitcher(
            duration: const Duration(milliseconds: 260),
            transitionBuilder: (c, a) => FadeTransition(
                opacity: a,
                child: SlideTransition(
                    position:
                        Tween(begin: const Offset(0.0, 0.4), end: Offset.zero)
                            .animate(a),
                    child: c)),
            child: Text(steps[_soRecStep.clamp(0, 2)],
                key: ValueKey(_soRecStep),
                textAlign: TextAlign.center,
                maxLines: 2,
                overflow: TextOverflow.ellipsis,
                style: _t(12.5, color: _ink3, weight: FontWeight.w500)),
          ),
        ),
      ]),
    );
  }

  /// วิเคราะห์แล้วไม่มีชุดที่ข้อมูลเคสรองรับพอ: บอกตรง ๆ + ค่าที่อ่านมา · ให้เลือกชุดเอง
  Widget _soRecNone() => Container(
        padding: const EdgeInsets.fromLTRB(16.0, 14.0, 16.0, 14.0),
        decoration: BoxDecoration(
          color: _panel,
          borderRadius: BorderRadius.circular(16.0),
          border: Border.all(color: const Color(0xFFDADCE0), width: 0.5),
        ),
        child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
          Text('ยังไม่มีชุดที่ตรงกับข้อมูลเคส',
              style: _t(15.0, color: _inkTitle, weight: FontWeight.w700)),
          const SizedBox(height: 4.0),
          for (final r in _soRecReads().take(2))
            Padding(
              padding: const EdgeInsets.only(top: 2.0),
              child: Text(r,
                  style: _t(12.5, color: _ink3, weight: FontWeight.w500)),
            ),
          const SizedBox(height: 10.0),
          _Press(
            child: GestureDetector(
              onTap: _soPickEnter,
              child: Container(
                height: 36.0,
                alignment: Alignment.center,
                decoration: BoxDecoration(
                  borderRadius: BorderRadius.circular(100.0),
                  border: Border.all(color: const Color(0xFFC4C7CC)),
                ),
                child: Text('เลือกชุดเอง',
                    style: _t(13.0, color: _blue, weight: FontWeight.w600)),
              ),
            ),
          ),
        ]),
      );

  /// recOnly = แสดงเฉพาะชุดที่แนะนำ (วางบนหน้า Order Set หลัก)
  /// selectedOnly: การ์ดชุดที่เลือกอยู่ใบเดียว (หน้า Standing Order หลัก) แบบการ์ดปกติ ไม่ใช่สี AI
  Widget _soPickPage({bool recOnly = false, bool selectedOnly = false}) {
    final cats = [
      for (final c in _templates) ...[
        if (c == 'Stroke') ...const [
          'Stroke Fast Tract',
          'Stroke Non Fast Tract'
        ] else
          c,
        if (c == 'Sepsis') 'Appendicitis',
      ],
    ];
    // แนะนำเฉพาะการ์ดบนหน้าหลัง (หลังกด AI แนะนำ) · หน้าเทมเพลต = เลือกเอง ไม่มีแนะนำ
    final rec = recOnly ? _soRecommend() : null;
    // ชื่อหมวดสั้นบนการ์ด
    String short(String g) => switch (g) {
          final x when x.startsWith('ยา') => 'การให้ยา',
          final x when x.startsWith('ภาพ') => 'X-ray',
          final x when x.startsWith('แล็บ') => 'Lab',
          _ => g,
        };

    // Figma 611:484: แต่ละ standing order = หัว (ชื่อ + คำอธิบาย) + ปุ่ม pill "เลือกใช้" ขวา
    // · การ์ดขาวขอบบาง มุม 16 = แถวหมวดกระจายเท่ากัน (ไอคอน + ชื่อหมวดหนา + จำนวนรายการ)
    // ไอคอน 3D จาก Figma (Lab 611:205 · ยา 614:524 · X-ray 615:637 · หัตถการ 615:685 · อื่น ๆ 615:721) · หมวดที่ยังไม่มีภาพ = ไอคอนระบบ
    Widget groupIcon(String name) => switch (name) {
          'Lab' => Image.asset('assets/images/er_os_lab.png',
              width: 22.0, height: 28.0, filterQuality: FilterQuality.medium),
          'การให้ยา' => Image.asset('assets/images/er_os_med.png',
              width: 21.0, height: 28.0, filterQuality: FilterQuality.medium),
          'X-ray' => Image.asset('assets/images/er_os_xray.png',
              width: 21.0, height: 28.0, filterQuality: FilterQuality.medium),
          'หัตถการ' => Image.asset('assets/images/er_os_proc_cap.png',
              width: 28.0, height: 28.0, filterQuality: FilterQuality.medium),
          'อื่น ๆ' => Image.asset('assets/images/er_os_other.png',
              width: 23.0, height: 28.0, filterQuality: FilterQuality.medium),
          _ => SizedBox(
              width: 28.0,
              height: 28.0,
              child: Icon(
                  switch (name) {
                    'การให้ยา' => Icons.medication_rounded,
                    'X-ray' => Icons.image_rounded,
                    'หัตถการ' => Icons.healing_rounded,
                    _ => Icons.more_horiz_rounded,
                  },
                  size: 26.0,
                  color: const Color(0xFF3D7BF2))),
        };

    // ชุดที่ใช้อยู่: เลือกในรอบนี้ · ยังไม่เลือก = ชุดของคำสั่งที่บันทึกล่าสุด (เคยสั่งแล้ว)
    final prevSet =
        _soPrev == null ? null : _soSetKey(_soPrev!.set).toLowerCase();
    final pickedNow = _soSetPicked.contains(_caseP().hn);
    Widget section(int idx, String cat) {
      final on = pickedNow
          ? cat == _template
          : prevSet != null &&
              (cat.toLowerCase() == prevSet ||
                  cat.toLowerCase().endsWith(' $prevSet'));
      final groups = [
        for (final (g, items) in _orderSetPages(cat))
          if (items.isNotEmpty) (short(g), items.length)
      ];
      final full = _soFullName[cat] ?? _setName(cat);
      // เลือกแล้วยังอยู่หน้าย่อยนี้ (เห็นว่าชุดไหน "ใช้อยู่") · กลับด้วยปุ่มย้อนกลับ/breadcrumb
      Future<void> pick() async {
        // แตะ "เลือกอยู่" ซ้ำ = ยกเลิกเลือก (กลับมาเห็นทุกชุด)
        if (on) {
          HapticFeedback.selectionClick();
          setState(() {
            _soSetPicked.remove(_caseP().hn);
            _soPickFocus = false;
          });
          return;
        }
        // หน้าย่อยเลือกชุด: เลือกอย่างเดียว ไม่เด้งเข้าหน้าเทมเพลต (เช่น Snake bite)
        // ชุดแบบเทมเพลตก็อยู่หน้านี้ต่อ เห็น "เลือกอยู่" + รายละเอียดเหมือนชุดอื่น
        if (!await _soConfirmReplace(cat)) return;
        HapticFeedback.selectionClick();
        setState(() {
          _template = cat;
          _orderEditing = null;
          _soSetPicked.add(_caseP().hn);
          _soDraftHn.add(_caseP().hn);
        });
        // เลือกแล้ว: กางรายละเอียด · ชุดนี้ขึ้นบนสุด ชุดอื่นซ่อน · เลื่อนกลับบนสุด
        setState(() {
          if (!recOnly) _soPickExpand[cat] = true;
          _soPickFocus = true;
        });
        // ชุดที่ AI แนะนำ: ติ๊กและกรอกรายละเอียดจากข้อมูลเคสให้เลย (ติดป้าย AI)
        if (rec?.$1 == cat) _soAiPrefill();
        // เลื่อนหน้ากลับบนสุดพร้อมกับชุดอื่นหุบ (ระยะเวลา/curve เดียวกัน = ไหลไปด้วยกัน)
        WidgetsBinding.instance.addPostFrameCallback((_) {
          final c = _soPickTopKey.currentContext;
          if (c == null || !c.mounted) return;
          final pos = Scrollable.maybeOf(c)?.position;
          if (pos == null || pos.pixels <= 0.0) return;
          pos.animateTo(0.0,
              duration: const Duration(milliseconds: 420),
              curve: Curves.easeInOutCubic);
        });
      }

      // กาง/หุบทั้งชุด: ปุ่มลูกศรท้ายแถวหมวด (หรือแตะการ์ด) · ชุดที่ใช้อยู่กางเป็นค่าเริ่ม
      // หน้า Order Set หลักเก็บสถานะกาง/หุบแยกจากหน้าเลือกชุด
      // ชุดที่เลือก/สั่งไว้แล้ว = กางเป็นค่าเริ่มทั้งสองหน้า (กลับเข้ามาเห็นรายการทันที)
      final ek = recOnly || selectedOnly ? 'main|$cat' : cat;
      final open = _soPickExpand[ek] ?? on;
      void toggle() {
        HapticFeedback.selectionClick();
        setState(() => _soPickExpand[ek] = !open);
      }

      final recd = rec?.$1 == cat;
      return Padding(
        padding: const EdgeInsets.only(bottom: 16.0),
        child: _Rise(
          index: idx,
          // ชุดที่แนะนำ: ทั้งกลุ่ม (หัว + การ์ด) อยู่บนพื้นไล่ฟ้าม่วงอ่อนทางซ้าย → ขาวทางขวา
          child: Container(
            padding: recd ? const EdgeInsets.all(12.0) : EdgeInsets.zero,
            decoration: recd
                ? BoxDecoration(
                    gradient: const LinearGradient(
                      begin: Alignment.centerLeft,
                      end: Alignment.centerRight,
                      colors: [
                        Color(0xFFE6EEFD),
                        Color(0xFFF1ECFC),
                        Colors.white
                      ],
                      stops: [0.0, 0.55, 1.0],
                    ),
                    borderRadius: BorderRadius.circular(20.0),
                  )
                : null,
            child: Column(
                crossAxisAlignment: CrossAxisAlignment.stretch,
                children: [
                  Row(crossAxisAlignment: CrossAxisAlignment.center, children: [
                    Expanded(
                      child: Column(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            // ชื่อชุด + ป้าย "แนะนำ" ข้างชื่อ (แนะนำจากข้อมูลเคส)
                            Row(children: [
                              Flexible(
                                child: Text(_setName(cat),
                                    maxLines: 1,
                                    overflow: TextOverflow.ellipsis,
                                    style: _t(15.0,
                                        color: _inkTitle,
                                        weight: FontWeight.w700)),
                              ),
                            ]),
                            const SizedBox(height: 4.0),
                            Text(
                                rec?.$1 == cat
                                    ? 'จากข้อมูลเคส: ${rec!.$2}'
                                    : full,
                                maxLines: 1,
                                overflow: TextOverflow.ellipsis,
                                style: _t(12.0,
                                    color: _ink3, weight: FontWeight.w500)),
                          ]),
                    ),
                    const SizedBox(width: 8.0),
                    // ปุ่มรอง pill ตัวกรมท่า · ยังไม่เลือก = ไม่มีพื้น (ขอบเทา) · เลือกอยู่ = พื้น surface + ติ๊ก
                    _Press(
                      child: GestureDetector(
                        onTap: pick,
                        child: AnimatedContainer(
                          duration: const Duration(milliseconds: 180),
                          height: 32.0,
                          padding: EdgeInsets.fromLTRB(
                              on ? 10.0 : 16.0, 0.0, 16.0, 0.0),
                          alignment: Alignment.center,
                          decoration: BoxDecoration(
                            // ชุดแนะนำ (ยังไม่เลือก) = pill ไล่สี AI ตัวขาว แทนป้าย "แนะนำ"
                            color: on
                                ? _panelSoft
                                : recd
                                    ? null
                                    : Colors.transparent,
                            gradient: !on && recd
                                ? const LinearGradient(colors: [
                                    Color(0xFF4285F4),
                                    Color(0xFF9B72CB),
                                    Color(0xFFD96570),
                                  ])
                                : null,
                            borderRadius: BorderRadius.circular(100.0),
                            border: !on && recd
                                ? null
                                : Border.all(
                                    color: on
                                        ? _panelSoft
                                        : const Color(0xFFDADCE0)),
                          ),
                          child: Row(mainAxisSize: MainAxisSize.min, children: [
                            if (on) ...[
                              const _SolarIcon('ph-check',
                                  size: 16.0, color: _blue),
                              const SizedBox(width: 4.0),
                            ],
                            if (!on && recd) ...[
                              const Icon(Icons.auto_awesome_rounded,
                                  size: 14.0, color: Colors.white),
                              const SizedBox(width: 4.0),
                            ],
                            Text(on ? 'เลือกอยู่' : 'เลือกใช้',
                                style: _t(13.0,
                                    color: !on && recd ? Colors.white : _blue,
                                    weight: FontWeight.w600)),
                          ]),
                        ),
                      ),
                    ),
                  ]),
                  const SizedBox(height: 8.0),
                  GestureDetector(
                    behavior: HitTestBehavior.opaque,
                    onTap: toggle,
                    child: Container(
                      clipBehavior: Clip.antiAlias,
                      decoration: BoxDecoration(
                        color: _panel,
                        borderRadius: BorderRadius.circular(16.0),
                        border: Border.all(
                            color: const Color(0xFFDADCE0), width: 0.5),
                      ),
                      child: Column(
                          crossAxisAlignment: CrossAxisAlignment.stretch,
                          children: [
                            // Figma 611:310: แถวสรุปหมวดคงอยู่ · กาง = กล่องเทาต่อหมวด
                            // (ชื่อหมวดเล็กสีเทา · รายการตัวหนา · ไอคอน 3D ใหญ่โผล่มุมขวาบน)
                            Padding(
                              padding: const EdgeInsets.fromLTRB(
                                  8.0, 16.0, 8.0, 14.0),
                              child: Row(children: [
                                for (final (name, n) in groups)
                                  Expanded(
                                    child: Column(children: [
                                      SizedBox(
                                          height: 28.0,
                                          child:
                                              Center(child: groupIcon(name))),
                                      const SizedBox(height: 8.0),
                                      Text(name,
                                          maxLines: 1,
                                          overflow: TextOverflow.ellipsis,
                                          style: _t(13.0,
                                              color: _inkTitle,
                                              weight: FontWeight.w700)),
                                      const SizedBox(height: 2.0),
                                      Text('$n รายการ',
                                          style: _t(11.0,
                                              color: _ink3,
                                              weight: FontWeight.w500)),
                                    ]),
                                  ),
                              ]),
                            ),
                            // แบบประวัติการวัด: หุบ = เห็นรายการบนสุดนิดหน่อยแล้วจาง · ปุ่ม "ดูรายการ"
                            AnimatedSize(
                              duration: const Duration(milliseconds: 320),
                              curve: Curves.easeInOutCubic,
                              alignment: Alignment.topCenter,
                              child: ConstrainedBox(
                                constraints: BoxConstraints(
                                    maxHeight: open ? double.infinity : 64.0),
                                child: ShaderMask(
                                  blendMode: BlendMode.dstIn,
                                  shaderCallback: (b) => LinearGradient(
                                    begin: Alignment.topCenter,
                                    end: Alignment.bottomCenter,
                                    colors: open
                                        ? const [Colors.black, Colors.black]
                                        : const [
                                            Colors.black,
                                            Colors.transparent
                                          ],
                                  ).createShader(b),
                                  // ตัดขอบแทน scroll view (เดิม scroll view จำตำแหน่งจาก PageStorage/แผง
                                  // หุบแล้วเห็นหมวดท้ายแทนหมวดแรก) · ชิดบนเสมอ
                                  child: ClipRect(
                                    child: UnconstrainedBox(
                                      constrainedAxis: Axis.horizontal,
                                      alignment: Alignment.topCenter,
                                      clipBehavior: Clip.hardEdge,
                                      child: Padding(
                                        padding: const EdgeInsets.fromLTRB(
                                            16.0, 0.0, 16.0, 16.0),
                                        child: Column(
                                            crossAxisAlignment:
                                                CrossAxisAlignment.stretch,
                                            children: [
                                              for (final (k, (g, items))
                                                  in _orderSetPages(cat)
                                                      .where((e) =>
                                                          e.$2.isNotEmpty)
                                                      .indexed)
                                                Padding(
                                                  padding:
                                                      const EdgeInsets.only(
                                                          top: 10.0),
                                                  child: _Rise(
                                                    index: k,
                                                    child: Stack(
                                                        clipBehavior: Clip.none,
                                                        children: [
                                                          Container(
                                                            width:
                                                                double.infinity,
                                                            padding:
                                                                const EdgeInsets
                                                                    .fromLTRB(
                                                                    12.0,
                                                                    10.0,
                                                                    56.0,
                                                                    12.0),
                                                            decoration:
                                                                BoxDecoration(
                                                              color: _panelSoft,
                                                              borderRadius:
                                                                  BorderRadius
                                                                      .circular(
                                                                          12.0),
                                                            ),
                                                            child: Column(
                                                                crossAxisAlignment:
                                                                    CrossAxisAlignment
                                                                        .start,
                                                                children: [
                                                                  Text(short(g),
                                                                      style: _t(
                                                                          12.0,
                                                                          color:
                                                                              _ink3,
                                                                          weight:
                                                                              FontWeight.w500)),
                                                                  const SizedBox(
                                                                      height:
                                                                          8.0),
                                                                  for (final it
                                                                      in items)
                                                                    Padding(
                                                                      padding: const EdgeInsets
                                                                          .only(
                                                                          bottom:
                                                                              5.0),
                                                                      child: Column(
                                                                          crossAxisAlignment:
                                                                              CrossAxisAlignment.start,
                                                                          children: [
                                                                            // Lab: หัว = ชื่อแบบฟอร์ม แล้วใบสั่ง → รายการ
                                                                            Text(_soLabSetOf(it)?.$1 ?? it,
                                                                                style: _t(13.5, color: _inkTitle, weight: FontWeight.w700)),
                                                                            if (_soLabSetOf(it)
                                                                                case (
                                                                                  final form,
                                                                                  final ts
                                                                                ))
                                                                              _soDocLabTree(form, ts, showForm: false),
                                                                          ]),
                                                                    ),
                                                                ]),
                                                          ),
                                                          // ไอคอน 3D ใหญ่โผล่เหนือขอบบนมุมขวา
                                                          Positioned(
                                                            right: 6.0,
                                                            top: -8.0,
                                                            child: SizedBox(
                                                              width: 40.0,
                                                              height: 48.0,
                                                              child: FittedBox(
                                                                  child: groupIcon(
                                                                      short(
                                                                          g))),
                                                            ),
                                                          ),
                                                        ]),
                                                  ),
                                                ),
                                            ]),
                                      ),
                                    ),
                                  ),
                                ),
                              ),
                            ),
                            Padding(
                              padding: const EdgeInsets.fromLTRB(
                                  16.0, 4.0, 16.0, 14.0),
                              child: _Press(
                                child: GestureDetector(
                                  onTap: toggle,
                                  child: Container(
                                    height: 36.0,
                                    alignment: Alignment.center,
                                    decoration: BoxDecoration(
                                      color: _panel,
                                      borderRadius:
                                          BorderRadius.circular(100.0),
                                      border: Border.all(
                                          color: const Color(0xFFC4C7CC)),
                                    ),
                                    child: Row(
                                        mainAxisSize: MainAxisSize.min,
                                        children: [
                                          Text(open ? 'ซ่อนรายการ' : 'ดูรายการ',
                                              style: _t(13.0,
                                                  color: _inkTitle,
                                                  weight: FontWeight.w600)),
                                          const SizedBox(width: 6.0),
                                          Icon(
                                              open
                                                  ? Icons
                                                      .keyboard_arrow_up_rounded
                                                  : Icons
                                                      .keyboard_arrow_down_rounded,
                                              size: 18.0,
                                              color: _inkTitle),
                                        ]),
                                  ),
                                ),
                              ),
                            ),
                          ]),
                    ),
                  ),
                ]),
          ),
        ),
      );
    }

    bool isOn(String c) => c == _template && _soSetPicked.contains(_caseP().hn);
    final picked = cats.any(isOn);
    if (selectedOnly) {
      return _soSetPicked.contains(_caseP().hn) && _template != _soCustom
          ? section(0, _template)
          : const SizedBox.shrink();
    }
    if (recOnly) {
      if (rec == null || !cats.contains(rec.$1)) return const SizedBox.shrink();
      return section(0, rec.$1);
    }

    return Column(
      key: const ValueKey('so-pick'),
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        SizedBox(key: _soPickTopKey, height: 0.0),
        // ลำดับคงที่ (ไม่สลับตำแหน่งกระโดด) · เลือกแล้ว = ชุดอื่นจาง + หุบพร้อมกัน
        // ชุดที่เลือกจึงเลื่อนขึ้นบนสุดเองแบบต่อเนื่อง (พร้อมเลื่อนหน้ากลับบนสุด)
        for (final (i, cat) in cats.indexed)
          Builder(builder: (context) {
            final hide = _soPickFocus && !isOn(cat) && picked;
            return AnimatedSize(
              key: ValueKey('set-$cat'),
              duration: const Duration(milliseconds: 420),
              curve: Curves.easeInOutCubic,
              alignment: Alignment.topCenter,
              child: AnimatedOpacity(
                opacity: hide ? 0.0 : 1.0,
                duration: const Duration(milliseconds: 220),
                curve: Curves.easeOut,
                child: hide
                    ? const SizedBox(width: double.infinity)
                    : section(i, cat),
              ),
            );
          }),
        if (_soPickFocus && picked)
          Center(
            child: TextButton.icon(
              onPressed: () {
                HapticFeedback.selectionClick();
                setState(() => _soPickFocus = false);
              },
              icon: const Icon(Icons.keyboard_arrow_down_rounded,
                  size: 20.0, color: _blue),
              label: Text('ดูชุดอื่น (${cats.length - 1})',
                  style: _t(13.0, color: _blue, weight: FontWeight.w600)),
            ),
          ),
      ],
    );
  }

  /// คำสั่งครั้งล่าสุดของเคส (ไม่มี = ยังไม่เคยสั่ง)
  _SoRound? get _soPrev => _soRoundsOf(_caseP().hn).firstOrNull;

  /// ประวัติคำสั่งของเคส (ใหม่ → เก่า): ที่บันทึกในแอป + ชุดตัวอย่าง (เคสที่ยังไม่เคยสั่ง = ไม่มีตัวอย่าง)
  List<_SoRound> _soRoundsOf(String hn) => [
        ...?_soSaved[hn],
        if (!_soNoOrderYet.contains(hn)) ..._soHistory,
      ];

  /// บันทึกแบบร่างเป็นคำสั่งครั้งใหม่ (กดบันทึกขั้นสั่งการรักษา): ครั้งที่ต่อจากเดิม เวลาตอนนี้
  /// ผู้สั่ง = แพทย์ที่ล็อกอิน · รายการ = แบบร่าง (One Day / Continuation) สถานะเริ่ม "รอรับ"
  void _soCommit() {
    final hn = _caseP().hn;
    // ต่อจากคำสั่งเดิม (สั่งเพิ่ม / แก้ไข): ครั้งใหม่ = ชุดเต็ม (รายการเดิมที่ยังคงไว้ พร้อมสถานะเดิม
    // + รายการใหม่ + "สั่งเพิ่ม ครั้งที่ N") · รายการเดิมที่เอาติ๊กออก (ยังไม่ทำ) = ยกเลิก
    // (เดิมเก็บเฉพาะรายการใหม่ = ครั้งล่าสุดเหลือแค่ที่สั่งเพิ่ม ดูเหมือนชุดเก่าหาย)
    final prev = _soContHn.contains(hn) ? _soPrev : null;
    final prevNames = {for (final o in prev?.items ?? const []) o.$1};
    final deck = [
      for (final x in _soDeckItems())
        if (x.section != 'Progress Note') x
    ];
    final items = [
      for (final x in deck)
        if (!(prevNames.contains(x.name) && !x.id.contains('#'))) x
    ];
    if (prev != null) {
      final kept = {
        for (final x in deck)
          if (!x.id.contains('#')) x.name
      };
      for (final o in prev.items) {
        if (!kept.contains(o.$1) && o.$3 != 'ทำแล้ว' && !_isDone(o.$1)) {
          _soCancelled.add('${prev.no}|${prev.time}|${o.$1}');
        }
      }
    }
    final keptPrev = [
      if (prev != null)
        for (final o in prev.items)
          if (!_soCancelled.contains('${prev.no}|${prev.time}|${o.$1}')) o
    ];
    // ไม่มีรายการใหม่ และไม่ได้ต่อจากคำสั่งเดิม = ไม่มีอะไรบันทึก
    // ต่อจากคำสั่งเดิมแต่แก้แค่ค่า = ยังบันทึกเป็นครั้งใหม่ (เห็นเวลา/ผู้แก้ ค่าใหม่ไม่ทับครั้งเดิม)
    if (items.isEmpty && keptPrev.isEmpty) {
      _soContHn.remove(hn);
      _soDraftHn.remove(hn);
      return;
    }
    // ชื่อที่บันทึก: สั่งเพิ่มซ้ำ (id 'ชื่อ#k') แยกชื่อ = งาน/ค่า/สถานะไม่ยุบรวมกับรายการเดิม
    String saved(_SoDeckItem x) => x.id.contains('#')
        ? '${x.name} (สั่งเพิ่ม ครั้งที่ ${x.id.split('#').last})'
        : x.name;
    final now = DateTime.now();
    final round = _SoRound(
      _soRoundsOf(hn).length + 1,
      '${now.hour.toString().padLeft(2, '0')}:${now.minute.toString().padLeft(2, '0')}',
      ErSession.instance.user?.name ?? 'แพทย์ผู้สั่ง',
      // เก็บรหัสชุด (ไม่ใช่ชื่อแสดง): ต่อจากคำสั่งเดิม / จัดหมวด / progress note อ้างด้วยรหัส
      // ชื่อแสดงใช้ _setName(set)
      _template,
      [
        // รายการเดิม: รายละเอียด/สถานะเดิม (ทำแล้วยังทำแล้ว)
        ...keptPrev,
        for (final x in items)
          (saved(x), _soDetailLine(x), 'รอรับ', x.section == 'One Day')
      ],
    );
    // สำเนาค่าที่กรอกของแต่ละรายการไว้กับครั้งนี้ (ประวัติไม่เปลี่ยนตามแบบร่างใหม่ / ผู้ป่วยอื่น)
    void snap(String from, String name) {
      final to = _soSnapId(hn, round, name);
      for (final e in [..._soVal.entries]) {
        if (e.key.startsWith('$from|')) {
          _soVal['$to|${e.key.substring(from.length + 1)}'] = e.value;
        }
      }
      if (_soNote[from] case final n?) _soNote[to] = n;
    }

    for (final x in deck) {
      if (!x.id.contains('#') && prevNames.contains(x.name) ||
          items.contains(x)) {
        snap(x.id, saved(x));
      }
    }
    // รายการเดิมที่ไม่ได้อยู่ในแบบร่าง (เช่น ทำแล้ว) = ใช้สำเนาของครั้งก่อน
    if (prev != null) {
      for (final o in keptPrev) {
        if (deck.any((x) => x.name == o.$1)) continue;
        snap(_soHistId(hn, prev, o.$1), o.$1);
      }
      // ผู้รับคำสั่งของรายการเดิมตามมาด้วย
      for (final o in keptPrev) {
        final a = _soAccepted['$hn|${prev.no}|${prev.time}|${o.$1}'];
        if (a != null) _soAccepted['$hn|${round.no}|${round.time}|${o.$1}'] = a;
      }
    }
    if (prev != null) {
      for (final o in keptPrev) {
        final c = _soSavedCat['${prev.no}|${prev.time}|${o.$1}'];
        if (c != null) _soSavedCat['${round.no}|${round.time}|${o.$1}'] = c;
        final d = _soDoneBy['${prev.time}|${o.$1}'];
        if (d != null) _soDoneBy['${round.time}|${o.$1}'] = d;
      }
    }
    // จำหมวดของแต่ละรายการตอนบันทึก (หมวดจริงจากแบบร่าง: รหัสในใบ หรือที่แพทย์แก้)
    for (final x in items) {
      _soSavedCat['${round.no}|${round.time}|${saved(x)}'] = _soCatsOf(x).first;
    }
    (_soSaved[hn] ??= []).insert(0, round);
    _soSel[hn] = 0;
    // บันทึกแล้ว = จบโหมดต่อจากคำสั่งเดิม (ครั้งหน้ากดสั่งเพิ่มจะอ้างครั้งล่าสุดใหม่)
    _soContHn.remove(hn);
    _soDraftHn.remove(hn);
  }

  /// คีย์สำเนาค่าของรายการ [name] ในคำสั่งครั้ง [r] ของผู้ป่วย [hn]
  String _soSnapId(String hn, _SoRound r, String name) =>
      'H:$hn:${r.no}:${r.time}:$name';

  /// id ที่ใช้อ่านค่าของรายการในประวัติ: มีสำเนา = สำเนา · ข้อมูลเก่า (ก่อนมีสำเนา) = ค่าตามชื่อ
  String _soHistId(String hn, _SoRound r, String name) {
    final id = _soSnapId(hn, r, name);
    return _soVal.keys.any((k) => k.startsWith('$id|')) ||
            _soNote.containsKey(id)
        ? id
        : name;
  }

  /// สถานะของรายการในคำสั่งเดิม (null = รายการใหม่ / ไม่ได้อยู่ในโหมดต่อจากคำสั่งเดิม)
  String? _soPrevStatus(String name) {
    if (!_soContHn.contains(_caseP().hn)) return null;
    final prev = _soPrev;
    if (prev == null) return null;
    for (final it in prev.items) {
      if (it.$1 != name) continue;
      // สถานะจริงตอนนี้ (ทำ/รับในภาพรวมหรือขั้นพยาบาลแล้ว = ทำแล้ว ตรงกับประวัติ)
      return _soOk(prev, name, it.$3) ? 'ทำแล้ว' : it.$3;
    }
    return null;
  }

  /// สั่งเพิ่ม / แก้ไขจากคำสั่งเดิม: ใช้ชุดเดิม ติ๊กรายการเดิมไว้ แล้วไปหน้าใบคำสั่ง
  void _soContinue() {
    final prev = _soPrev;
    if (prev == null) return;
    HapticFeedback.selectionClick();
    setState(() {
      _template = _soSetKey(prev.set);
      _orderEditing = null;
      _soSetPicked.add(_caseP().hn);
      _soDraftHn.add(_caseP().hn);
      _soContHn.add(_caseP().hn);
      // แบบร่างเริ่มจากคำสั่งเดิมพอดี (ล้างติ๊ก/สั่งเพิ่มค้างจากแบบร่างก่อน กันบันทึกซ้ำ)
      // รายการที่ยกเลิกไปแล้วไม่ติ๊กกลับมา
      _orderPicked
        ..clear()
        ..addAll([
          for (final it in prev.items)
            if (!_soCancelled.contains('${prev.no}|${prev.time}|${it.$1}'))
              it.$1
        ]);
      _soMore.removeWhere((k, _) => k.startsWith('$_template|'));
      // ค่าที่บันทึกไว้ในครั้งล่าสุด (สำเนา) กลับเข้าแบบร่าง = แบบร่างตรงกับที่เห็นในประวัติ
      final hn = _caseP().hn;
      for (final it in prev.items) {
        final snap = _soSnapId(hn, prev, it.$1);
        final keys = [
          for (final k in _soVal.keys)
            if (k.startsWith('$snap|')) k
        ];
        if (keys.isEmpty) continue;
        _soVal.removeWhere((k, _) => k.startsWith('${it.$1}|'));
        for (final k in keys) {
          _soVal['${it.$1}|${k.substring(snap.length + 1)}'] = _soVal[k]!;
        }
        if (_soNote[snap] case final n?) _soNote[it.$1] = n;
      }
    });
    final seq = _uiSeq;
    _pageGo(seq, _pageAt(seq) + 1);
  }

  /// การ์ดคำสั่งเดิม (หน้าแรกของขั้น): ชุด ครั้งที่ เวลา ผู้สั่ง ความคืบหน้า · ปุ่มเดียว สั่งเพิ่ม / แก้ไข
  /// วันที่ไทยแบบย่อ เช่น 29 ต.ค. 2569
  String _thDateShort(DateTime d) {
    const m = [
      'ม.ค.', 'ก.พ.', 'มี.ค.', 'เม.ย.', 'พ.ค.', 'มิ.ย.', //
      'ก.ค.', 'ส.ค.', 'ก.ย.', 'ต.ค.', 'พ.ย.', 'ธ.ค.'
    ];
    return '${d.day} ${m[d.month - 1]} ${d.year + 543}';
  }

  /// ผลที่บันทึกล่าสุดของงาน (รอบ, ค่า) · ไม่มี = null
  (int, Map<String, String>)? _soLastRec(String hn, String name) {
    (int, Map<String, String>)? best;
    for (final e in _taskRec.entries) {
      if (!e.key.startsWith('$hn|$name|') || e.value.isEmpty) continue;
      final k = int.tryParse(e.key.split('|').last) ?? 0;
      if (best == null || k > best.$1) best = (k, e.value);
    }
    return best;
  }

  /// ผู้รับคำสั่งของรายการในครั้ง [r] (รับในแอป หรือค่าจำลอง)
  (String, String)? _soGot(String hn, _SoRound r, String name) =>
      _soAccepted['$hn|${r.no}|${r.time}|$name'] ??
      _soAcceptedMock['${r.time}|$name'];

  /// คำสั่งทำเป็นรอบ/ตามความถี่ ที่ยังมีรอบเหลือ (ยังไม่ครบ = ยังไม่นับว่าทำเสร็จ)
  bool _soRoundsLeft(String hn, _SoRound r, String name) {
    final o = r.items.where((x) => x.$1 == name).firstOrNull;
    if (o == null) return false;
    final now = DateTime.now();
    DateTime hm(String t) {
      final p = t.split(':');
      return DateTime(
          now.year, now.month, now.day, int.parse(p[0]), int.parse(p[1]));
    }

    // ×N + ระยะห่าง: เทียบจำนวนรอบที่ทำแล้ว
    if (_soRoundSpec('$name ${o.$2}') case (final n, _)) {
      final rec = math.max((_taskRounds['$hn|$name'] ?? const []).length,
          (_soRoundsMock['${r.time}|$name'] ?? const []).length);
      return rec < n;
    }
    // ความถี่ที่สั่ง (วันละ k ครั้ง / ทุก N): ยังมีเวลาให้หลังรอบที่ทำล่าสุด = ยังไม่ครบ
    final d = _soDoneBy['${r.time}|$name'];
    final it = _SoDeckItem(
        _soHistId(hn, r, name),
        name,
        o.$4 ? 'One Day' : 'Continuation',
        _soRoundCatOf(r, name),
        _soTones[1],
        '',
        hm(r.time),
        d == null ? null : (d.$1, hm(d.$2)));
    if (_soFreqOf(it) == null) return false;
    final times = _soDoseTimes(it).$1;
    return times.any((t) => d == null || t.isAfter(hm(d.$2)));
  }

  /// ฟอร์มบันทึกผลของคำสั่ง: ที่ตั้งไว้ หรือเดาจากชื่อคำสั่ง (ชุดสำเร็จรูปที่ชื่อตรง)
  /// ช่องที่แพทย์กรอกตอนสั่ง: ที่ตั้งไว้ หรือแปลงจากช่องเว้นว่างเดิมของใบ
  List<_MField> _soDrFormFor(String name) =>
      _soDrForms[name] ??
      [
        for (final (l, u) in _soBlanks[name] ?? const <(String, String)>[])
          _MField(l,
              type: l.contains('เวลา')
                  ? 'time'
                  : u.isEmpty || u.contains('/') && !u.contains('ml')
                      ? 'text'
                      : 'num',
              unit: u),
      ];

  List<(String, String)> _soBlanksOf(_SoDeckItem it) =>
      _soDrForms[it.name] != null
          ? [
              for (final f in _soDrForms[it.name]!)
                if (!_mIsBlock(f)) (f.label, f.unit)
            ]
          : _soBlanks[it.id] ?? const <(String, String)>[];

  List<_MField> _soFormFor(String name) =>
      _soForms[name] ??
      [
        for (final (_, re, make) in _soFormPresets)
          if (RegExp(re).hasMatch(name.toLowerCase())) ...make(),
      ];

  /// ช่องเดียวของฟอร์มบันทึกผล (ใช้ทั้งหน้ากรอกของพยาบาลและตัวอย่างในหน้าสร้างฟอร์ม)
  /// [m] = ค่าที่กรอก (ชื่อช่อง → ค่า) · preview = แตะไม่ได้
  Widget _mFieldView(
      _MField f, Map<String, String> m, void Function(VoidCallback) set,
      {bool preview = false,
      String key = '',
      bool showErr = false,
      bool live = false}) {
    // ตัวอย่างในตัวสร้างฟอร์ม: วาดรายการ V/S แบบนิ่ง (การ์ดจริงมี GlobalKey ซ้ำเมื่อวางหลายที่)
    // ฟอร์มสั่งจริง: ในตัวสร้างฟอร์มแตะข้อย่อยเพื่อตั้งค่าเริ่มต้นได้ (live)
    // ตอนสั่งจริงหน้าแพทย์วาดฟอร์มนี้เองตามหมวด โดยเริ่มจากค่าที่ตั้งไว้
    if (f.type == 'rx' || f.type == 'proc') {
      final rx = f.type == 'rx';
      final id = f.blockId ?? 'sopreview|${f.type}';
      final it = _SoDeckItem(
          id, f.label, 'One Day', rx ? 'Medication' : 'Procedure', _blue);
      Widget form() {
        final parts = rx
            ? _soMedForm<(String, Widget)>(it, (t, w) => (t, w))
            : _soProcForm<(String, Widget)>(it, (t, w) => (t, w));
        return Column(
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              for (final (t, w) in parts) ...[
                if (t != it.name)
                  Padding(
                    padding: const EdgeInsets.only(top: 8.0, bottom: 4.0),
                    child: Text(t,
                        style: _t(14.0,
                            color: _inkTitle, weight: FontWeight.w600)),
                  ),
                w,
              ],
            ]);
      }

      return live
          ? _SoBlockLive(sig: () => _soBlockSig(id), builder: form)
          : IgnorePointer(child: form());
    }
    if (f.type == 'vs' && preview) {
      return Column(children: [
        for (final (i, (k, l, u)) in const [
          ('wt', 'น้ำหนัก', 'kg'),
          ('ht', 'ส่วนสูง', 'cm'),
          ('sbp', 'ความดันโลหิต', 'mmHg'),
          ('hr', 'อัตราการเต้นหัวใจ', 'bpm'),
          ('rr', 'การหายใจ', '/min'),
          ('bt', 'อุณหภูมิ', '°C'),
          ('spo2', 'ออกซิเจนในเลือด', '%'),
        ].indexed) ...[
          if (i > 0)
            const Divider(
                height: 1.0, thickness: 1.0, color: Color(0xFFE8EAED)),
          Padding(
            padding: const EdgeInsets.symmetric(vertical: 10.0),
            child: Row(children: [
              _vsFigmaIcon(k, size: 36.0) ?? const SizedBox(width: 36.0),
              const SizedBox(width: 14.0),
              Expanded(
                child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text(l,
                          style: _t(14.5,
                              color: _inkTitle, weight: FontWeight.w600)),
                      Text('ยังไม่วัด  $u',
                          style:
                              _t(12.5, color: _ink3, weight: FontWeight.w500)),
                    ]),
              ),
              const Icon(Icons.chevron_right_rounded, size: 22.0, color: _ink3),
            ]),
          ),
        ],
      ]);
    }
    if (f.type == 'vs') {
      _qCardNarrow = true;
      final flat = _qFlat;
      _qFlat = true;
      final card = _triAssessCards().first;
      _qFlat = flat;
      _qCardNarrow = false;
      return IgnorePointer(ignoring: preview, child: card);
    }
    final label = f.label.trim().isEmpty ? 'ยังไม่ตั้งชื่อ' : f.label;
    final opts = [
      for (final o in f.opts)
        if (o.trim().isNotEmpty) o
    ];
    Widget chip(String o, bool on, VoidCallback tap) => ChoiceChip(
          label: Text(o),
          selected: on,
          showCheckmark: f.type == 'checks',
          labelStyle:
              _t(13.5, color: on ? _blue : _inkTitle, weight: FontWeight.w600),
          selectedColor: _blue.withValues(alpha: 0.08),
          checkmarkColor: _blue,
          backgroundColor: _panel,
          side: BorderSide(
              color: on ? Colors.transparent : const Color(0xFFDADCE0)),
          shape: const StadiumBorder(),
          // ตัวอย่าง: กดได้ (ห่อ IgnorePointer จากข้างนอก) ไม่ให้เป็นสีเทาแบบปุ่มปิด
          onSelected: (_) => set(tap),
        );
    InputDecoration dec(String hint) => InputDecoration(
          isDense: true,
          hintText: hint,
          hintStyle: _t(14.0, color: _ink3),
          filled: true,
          fillColor: const Color(0xFFF1F3F6),
          contentPadding:
              const EdgeInsets.symmetric(horizontal: 14.0, vertical: 12.0),
          border: OutlineInputBorder(
              borderRadius: BorderRadius.circular(12.0),
              borderSide: BorderSide.none),
        );
    final cur = m[f.label] ?? '';
    final view = f.view ??
        switch (f.type) {
          'yesno' => 'segment',
          'choice' || 'checks' => 'chips',
          _ => 'input',
        };
    String numText(double v) =>
        v == v.roundToDouble() ? v.toStringAsFixed(0) : v.toStringAsFixed(1);
    final step = (f.step ?? 0.0) > 0.0 ? f.step! : 1.0;
    // ปุ่มกลม − + ของตัวนับ (แตะได้ 44)
    Widget stepBtn(IconData ic, double? to) => Material(
          color: _panel,
          shape: CircleBorder(
              side: BorderSide(
                  color: to == null
                      ? const Color(0xFFE8EAED)
                      : const Color(0xFFC4C7CC))),
          clipBehavior: Clip.antiAlias,
          child: InkWell(
            onTap: to == null
                ? null
                : () {
                    HapticFeedback.selectionClick();
                    set(() => m[f.label] = numText(to));
                  },
            child: SizedBox.square(
                dimension: 44.0,
                child: Icon(ic, size: 22.0, color: to == null ? _ink3 : _blue)),
          ),
        );
    // แถวตัวเลือกแบบรายการ: วงกลม / ช่องติ๊ก + ชื่อ คั่นเส้นบาง
    Widget listRow(String o, bool on, VoidCallback tap, bool many) => InkWell(
          onTap: () {
            HapticFeedback.selectionClick();
            set(tap);
          },
          child: Container(
            constraints: const BoxConstraints(minHeight: 48.0),
            decoration: const BoxDecoration(
                border: Border(bottom: BorderSide(color: Color(0xFFE8EAED)))),
            child: Row(children: [
              Icon(
                  many
                      ? (on
                          ? Icons.check_box_rounded
                          : Icons.check_box_outline_blank_rounded)
                      : (on
                          ? Icons.radio_button_checked_rounded
                          : Icons.radio_button_unchecked_rounded),
                  size: 22.0,
                  color: on ? _blue : _ink3),
              const SizedBox(width: 12.0),
              Expanded(
                child: Text(o,
                    style: _t(14.5, color: _inkTitle, weight: FontWeight.w500)),
              ),
            ]),
          ),
        );
    // แถบแบ่งช่องกว้างเท่ากัน: เลือก = ฟ้าอ่อน
    Widget segment() => Container(
          padding: const EdgeInsets.all(3.0),
          decoration: BoxDecoration(
              color: const Color(0xFFF1F3F6),
              borderRadius: BorderRadius.circular(12.0)),
          child: Row(children: [
            for (final o in opts)
              Expanded(
                child: GestureDetector(
                  behavior: HitTestBehavior.opaque,
                  onTap: () {
                    HapticFeedback.selectionClick();
                    set(() => m[f.label] = o);
                  },
                  child: AnimatedContainer(
                    duration: const Duration(milliseconds: 160),
                    height: 40.0,
                    alignment: Alignment.center,
                    decoration: BoxDecoration(
                      color: cur == o ? _panel : Colors.transparent,
                      borderRadius: BorderRadius.circular(9.0),
                      border: cur == o
                          ? Border.all(color: _blue)
                          : Border.all(color: Colors.transparent),
                    ),
                    child: Text(o,
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                        style: _t(14.0,
                            color: cur == o ? _blue : _ink2,
                            weight: FontWeight.w600)),
                  ),
                ),
              ),
          ]),
        );
    final none = Text('ยังไม่มีตัวเลือก',
        style: _t(13.0, color: _ink3, weight: FontWeight.w500));
    final body = switch ((f.type, view)) {
      // ตัวนับ: − ค่าตัวใหญ่ (หน่วย) + · หยุดที่ขอบช่วง · เริ่มที่ค่าต่ำสุด
      ('num', 'counter') => Builder(builder: (_) {
          final v = double.tryParse(cur);
          final from = v ?? f.min ?? 0.0;
          bool ok(double x) =>
              (f.min == null || x >= f.min!) && (f.max == null || x <= f.max!);
          final dn = v == null ? from : from - step;
          final up = v == null ? from : from + step;
          return Row(children: [
            stepBtn(Icons.remove_rounded, v != null && ok(dn) ? dn : null),
            Expanded(
              child: Text.rich(
                  TextSpan(children: [
                    TextSpan(
                        text: v == null ? '–' : numText(v),
                        style: _num(24.0,
                            color: v == null ? _ink3 : _inkTitle,
                            weight: FontWeight.w700)),
                    if (f.unit.isNotEmpty)
                      TextSpan(
                          text: ' ${f.unit}',
                          style:
                              _t(13.0, color: _ink3, weight: FontWeight.w500)),
                  ]),
                  textAlign: TextAlign.center),
            ),
            stepBtn(Icons.add_rounded, ok(up) ? up : null),
          ]);
        }),
      // แถบเลื่อน: ค่าตัวใหญ่ + แถบ + ค่าต่ำสุด/สูงสุดใต้แถบ
      ('num', 'slider') => Builder(builder: (_) {
          final lo = f.min ?? 0.0, hi = f.max ?? 100.0;
          final v = double.tryParse(cur);
          final n = ((hi - lo) / step).round();
          return Column(
              crossAxisAlignment: CrossAxisAlignment.stretch,
              children: [
                Text.rich(
                    TextSpan(children: [
                      TextSpan(
                          text: v == null ? '–' : numText(v),
                          style: _num(22.0,
                              color: v == null ? _ink3 : _inkTitle,
                              weight: FontWeight.w700)),
                      if (f.unit.isNotEmpty)
                        TextSpan(
                            text: ' ${f.unit}',
                            style: _t(13.0,
                                color: _ink3, weight: FontWeight.w500)),
                    ]),
                    textAlign: TextAlign.center),
                SliderTheme(
                  // เส้นต่อเนื่อง ไม่มีจุดทุกขั้น (ช่วงกว้างจุดถี่จนรก)
                  data: SliderTheme.of(context)
                      .copyWith(tickMarkShape: SliderTickMarkShape.noTickMark),
                  child: Slider(
                    value: (v ?? lo).clamp(lo, hi > lo ? hi : lo + 1.0),
                    min: lo,
                    max: hi > lo ? hi : lo + 1.0,
                    divisions: n > 0 && n <= 200 ? n : null,
                    activeColor: _blue,
                    inactiveColor: const Color(0xFFE2EAF8),
                    onChanged: (x) => set(() => m[f.label] = numText(x)),
                  ),
                ),
                Row(children: [
                  Text(numText(lo),
                      style: _num(12.5, color: _ink3, weight: FontWeight.w500)),
                  const Spacer(),
                  Text(numText(hi),
                      style: _num(12.5, color: _ink3, weight: FontWeight.w500)),
                ]),
              ]);
        }),
      // ปุ่มคะแนน: เรียงกว้างเท่ากัน เลือก = กรมท่าทึบ
      ('num', 'scale') => Builder(builder: (_) {
          final lo = f.min ?? 0.0, hi = f.max ?? 10.0;
          final n = ((hi - lo) / step).floor();
          final vals = [
            for (var i = 0; i <= n && i <= 20; i++) numText(lo + i * step)
          ];
          return Row(children: [
            for (final (i, x) in vals.indexed) ...[
              if (i > 0) const SizedBox(width: 3.0),
              Expanded(
                child: GestureDetector(
                  behavior: HitTestBehavior.opaque,
                  onTap: () {
                    HapticFeedback.selectionClick();
                    set(() => m[f.label] = x);
                  },
                  child: AnimatedContainer(
                    duration: const Duration(milliseconds: 140),
                    height: 44.0,
                    alignment: Alignment.center,
                    decoration: BoxDecoration(
                      color: cur == x ? _blue : const Color(0xFFF1F3F6),
                      borderRadius: BorderRadius.circular(9.0),
                    ),
                    child: Text(x,
                        style: _num(14.0,
                            color: cur == x ? Colors.white : _ink2,
                            weight: FontWeight.w700)),
                  ),
                ),
              ),
            ],
          ]);
        }),
      ('yesno', 'switch') => Align(
          alignment: Alignment.centerRight,
          child: Switch(
            value: opts.isNotEmpty && cur == opts.first,
            activeThumbColor: Colors.white,
            activeTrackColor: _blue,
            onChanged: (on) => set(() => m[f.label] = on
                ? (opts.firstOrNull ?? '')
                : (opts.length > 1 ? opts[1] : '')),
          ),
        ),
      ('choice' || 'yesno', 'segment') => opts.isEmpty ? none : segment(),
      ('choice', 'list') => opts.isEmpty
          ? none
          : Column(mainAxisSize: MainAxisSize.min, children: [
              for (final o in opts)
                listRow(o, cur == o, () => m[f.label] = o, false),
            ]),
      ('checks', 'list') => opts.isEmpty
          ? none
          : Column(mainAxisSize: MainAxisSize.min, children: [
              for (final o in opts)
                listRow(o, cur.split(', ').contains(o), () {
                  final set0 = {
                    for (final x in cur.split(', '))
                      if (x.isNotEmpty) x
                  };
                  set0.contains(o) ? set0.remove(o) : set0.add(o);
                  m[f.label] = [
                    for (final x in opts)
                      if (set0.contains(x)) x
                  ].join(', ');
                }, true),
            ]),
      ('choice' || 'yesno', _) =>
        Wrap(spacing: 8.0, runSpacing: 8.0, children: [
          for (final o in opts) chip(o, cur == o, () => m[f.label] = o),
          if (opts.isEmpty) none,
        ]),
      ('checks', _) => Wrap(spacing: 8.0, runSpacing: 8.0, children: [
          for (final o in opts)
            chip(o, cur.split(', ').contains(o), () {
              final set0 = {
                for (final x in cur.split(', '))
                  if (x.isNotEmpty) x
              };
              set0.contains(o) ? set0.remove(o) : set0.add(o);
              m[f.label] = [
                for (final x in opts)
                  if (set0.contains(x)) x
              ].join(', ');
            }),
          if (opts.isEmpty) none,
        ]),
      // เวลา: แผ่นเลือกวันเวลาชุดเดียวกับเวลาที่ทำ
      ('time', _) => InkWell(
          onTap: preview
              ? null
              : () async {
                  final now = DateTime.now();
                  final d = await _dtSheet(
                      title: label,
                      initial: now,
                      first: now.subtract(const Duration(days: 1)),
                      last: now);
                  if (d != null) set(() => m[f.label] = _taskClock(d));
                },
          borderRadius: BorderRadius.circular(12.0),
          child: InputDecorator(
            decoration: dec('เลือกเวลา'),
            isEmpty: cur.isEmpty,
            child: Text(cur,
                style: _t(15.0, color: _inkTitle, weight: FontWeight.w600)),
          ),
        ),
      _ => TextFormField(
          key: ValueKey('mf-$key-${f.label}'),
          readOnly: preview,
          initialValue: m[f.label],
          minLines: f.type == 'long' ? 3 : 1,
          maxLines: f.type == 'long' ? 5 : 1,
          keyboardType: f.type == 'num'
              ? TextInputType.numberWithOptions(
                  decimal: true, signed: (f.min ?? 0.0) < 0.0)
              : TextInputType.text,
          inputFormatters: f.type == 'num'
              ? _mNumFormat(negative: (f.min ?? 0.0) < 0.0)
              : null,
          onChanged: (v) {
            m[f.label] = v;
            // เตือนอยู่ = แก้แล้วข้อความเตือนหายทันที
            if (showErr) set(() {});
          },
          style: _t(15.0, color: _inkTitle, weight: FontWeight.w600),
          decoration: dec(f.unit.isNotEmpty
              ? f.unit
              : f.type == 'num'
                  ? 'ตัวเลข'
                  : 'ข้อความ'),
        ),
    };
    // ข้อความเตือนใต้ช่อง (หลังกดบันทึกแล้วค่าไม่ผ่าน)
    final err = showErr ? _mErr(f, m[f.label]) : null;
    final control = err == null
        ? body
        : Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
            body,
            const SizedBox(height: 4.0),
            Text(err, style: _t(12.5, color: _red, weight: FontWeight.w600)),
          ]);
    final title = Text.rich(
        TextSpan(children: [
          TextSpan(text: label),
          if (f.req)
            TextSpan(
                text: ' *',
                style: _t(13.5, color: _red, weight: FontWeight.w700)),
        ]),
        style: _t(13.5, color: _ink2, weight: FontWeight.w500));
    // ชื่อช่องอยู่บน ช่องกรอกเต็มกว้าง แบบหน้าระบุรายละเอียดคำสั่ง (ทั้งหน้ากรอกและตัวอย่างในตัวสร้างฟอร์ม)
    return Padding(
      padding: const EdgeInsets.only(top: 12.0),
      child: Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
        title,
        const SizedBox(height: 8.0),
        control,
      ]),
    );
  }

  // เล่าเรื่องตอนเปิดตัวสร้างฟอร์ม (เวลาเดียวกันทั้งหน้า 0..1 จาก _SoIntro · แตะ = ข้ามไปท้าย):
  // 0.00-0.18 จอจำลองจางเข้า · 0.18-0.38 พยาบาลแตะคำสั่งนี้ทางซ้าย
  // 0.38-0.55 แผงกรอกเปิดทางขวา รายการอื่นจาง · 0.55-1.00 กล้องซูมเข้าแผง เครื่องมือเลื่อนเข้า

  /// แผงข้างของตัวสร้างฟอร์ม: กว้างจาก 0 ท้ายเรื่อง (เนื้อหาไม่บีบ ตัดขอบแทน)
  Widget _soCamSide(
          Animation<double> anim, double w, Alignment from, Widget child,
          {double open = 1.0}) =>
      AnimatedBuilder(
        animation: anim,
        builder: (_, c) => SizedBox(
          width: w *
              open *
              Curves.easeInOutCubic
                  .transform(((anim.value - 0.7) / 0.3).clamp(0.0, 1.0)),
          child: ClipRect(
            child: OverflowBox(
                alignment: from, minWidth: w, maxWidth: w, child: c),
          ),
        ),
        child: child,
      );

  /// หัวกลางจอเล่าว่าเกิดอะไรขึ้น ระหว่างเรื่องเท่านั้น จบแล้วเหลือริบบิ้นมุมการ์ด
  Widget _soCamCaption(Animation<double> anim, String name) => AnimatedBuilder(
        animation: anim,
        builder: (_, __) {
          final v = anim.value;
          final t = v < 0.38
              ? 'พยาบาลแตะคำสั่ง $name'
              : v < 0.55
                  ? 'หน้ากรอกเปิดขึ้นทางขวา'
                  : '';
          return AnimatedSwitcher(
            duration: const Duration(milliseconds: 240),
            child: Text(t,
                key: ValueKey(t),
                textAlign: TextAlign.center,
                maxLines: 1,
                overflow: TextOverflow.ellipsis,
                style: _t(14.0, color: _ink2, weight: FontWeight.w600)),
          );
        },
      );

  /// กลางจอ: จอจำลองทั้งจอ (แผงอยู่ตำแหน่งจริงทางขวา) → แผงเปิด → กล้องเลื่อนซูมเข้าแผง จอรอบ ๆ จางออก
  /// แผงเป็นตัวจริงตลอด ไม่สร้างใหม่ (แก้ได้ทันทีที่กล้องเข้าที่)
  Widget _soCameraIn(Animation<double> anim, String name, Widget panel) =>
      LayoutBuilder(builder: (context, box) {
        const sx = 693.0, sy = 74.0, sw = 340.0, wW = 1133.0, wH = 712.0;
        final cw = box.maxWidth, ch = box.maxHeight;
        final pw = math.min(cw - 32.0, 368.0);
        final ph = ch - 16.0;
        final pl = (cw - pw) / 2.0;
        final k = pw / sw;
        final fit = math
            .min((cw - 40.0) / (wW * k), (ch - 72.0) / (wH * k))
            .clamp(0.1, 1.0);
        final worldL = pl - sx * k, worldT = -sy * k;
        final cx = cw / 2.0, cy = ch / 2.0;
        final sc = Offset(worldL + wW * k / 2.0, worldT + wH * k / 2.0);
        return ClipRect(
          child: AnimatedBuilder(
            animation: anim,
            builder: (_, c) {
              final v = anim.value;
              final t = Curves.easeInOutCubic
                  .transform(((v - 0.55) / 0.45).clamp(0.0, 1.0));
              final s = fit + (1.0 - fit) * t;
              final fx = sc.dx + (cx - sc.dx) * t;
              final fy = sc.dy + (cy - sc.dy) * t;
              final m = Matrix4.identity()
                ..setEntry(0, 0, s)
                ..setEntry(1, 1, s)
                ..setEntry(0, 3, cx - fx * s)
                ..setEntry(1, 3, cy - fy * s);
              final fade = 1.0 - ((t - 0.4) / 0.6).clamp(0.0, 1.0);
              final open = Curves.easeOutCubic
                  .transform(((v - 0.38) / 0.17).clamp(0.0, 1.0));
              return Transform(
                transform: m,
                child: Stack(clipBehavior: Clip.none, children: [
                  Positioned(
                    left: worldL,
                    top: worldT,
                    width: wW * k,
                    height: wH * k,
                    child: fade <= 0.0
                        ? const SizedBox.shrink()
                        : IgnorePointer(
                            child: Opacity(
                              opacity: fade,
                              child: FittedBox(
                                alignment: Alignment.topLeft,
                                child: SizedBox(
                                    width: wW,
                                    height: wH,
                                    child: _soScreenMock(name, v)),
                              ),
                            ),
                          ),
                  ),
                  Positioned(
                    left: pl,
                    top: 0.0,
                    width: pw,
                    height: ph,
                    child: Opacity(
                      opacity: open,
                      child: Transform.translate(
                          offset: Offset(0.0, 28.0 * (1.0 - open)), child: c),
                    ),
                  ),
                ]),
              );
            },
            child: panel,
          ),
        );
      });

  /// จอหน้าผู้ป่วยจำลองรอบแผงกรอก (1133×712 = จอจริงไม่รวมแถบสถานะ ตำแหน่งวัดจากจอจริงของพยาบาล) ตามจังหวะเรื่อง [v]:
  /// หัวเคส · รางซ้าย · หน้าคำสั่งแพทย์ (แถวบน = คำสั่งนี้ มีจุดแตะ) · แผงขวาว่าง · รางขั้นขวา
  Widget _soScreenMock(String name, double v) {
    const line = Color(0xFFE4E7EB);
    final tap = ((v - 0.18) / 0.2).clamp(0.0, 1.0);
    final opened = v >= 0.38;
    // รายการอื่นจางเมื่อแผงเปิด
    final dim = 1.0 - 0.65 * ((v - 0.38) / 0.17).clamp(0.0, 1.0);
    Widget bar(double w, [double h = 10.0]) => Container(
        width: w,
        height: h,
        decoration: BoxDecoration(
            color: line, borderRadius: BorderRadius.circular(h / 2.0)));
    // ช่องรางเดียวกับของจริง: ไอคอน 24 + ชื่อ 10.5 · เลือก = แผ่นขาวต่อเข้าแผง · skel = เมนูอื่นเป็นแถบเทา ให้เด่นเฉพาะเมนูของเรื่องนี้
    Widget cell(int i, double x, double w, Widget icon, String t, bool on,
            BorderRadius radius,
            {bool skel = false}) =>
        Positioned(
          left: x,
          top: 74.0 + i * 69.0,
          width: w,
          height: 65.0,
          child: Container(
            decoration: BoxDecoration(
                color: on ? _panel : Colors.transparent, borderRadius: radius),
            child:
                Column(mainAxisAlignment: MainAxisAlignment.center, children: [
              if (skel)
                Container(
                    width: 24.0,
                    height: 24.0,
                    decoration: BoxDecoration(
