  /// บรรทัดคำสั่งของชุด = ใบ standing order + ที่แพทย์เพิ่มเอง
  List<(String, String, String, bool)> _soLinesOf(String t) =>
      [...?_soDocs[t], ...?_soExtra[t]];

  /// รายการในแฟ้มที่ติ๊กได้ (ไม่รวมคำสั่งเดิมที่ทำแล้ว)
  List<String> _soFolderIds(int fid) {
    final f = _soFolders().where((x) => x.$1 == fid).firstOrNull;
    if (f == null) return const [];
    return [
      for (final it in f.$3)
        if (_soPrevStatus(it.$1) != 'ทำแล้ว') '${f.$5}${it.$1}'
    ];
  }

  /// เลือกทั้งหมด / ล้างที่เลือก ของแฟ้ม
  void _soSelectAll(int fid) {
    final f = _soFolders().where((x) => x.$1 == fid).firstOrNull;
    if (f == null) return;
    final ids = _soFolderIds(fid);
    final all = ids.every(f.$4.contains);
    HapticFeedback.selectionClick();
    setState(() {
      if (all) {
        f.$4.removeAll(ids);
        for (final id in ids) {
          _soDone.remove(id);
          _soAi.remove(id);
        }
      } else {
        f.$4.addAll(ids);
      }
    });
  }

  /// AI แนะนำในแฟ้ม: ติ๊กรายการที่เข้ากับเคส · ข้ามยาที่ชนประวัติแพ้ ·
  /// ข้ามรายการมีเงื่อนไข (ถ้า… / Stop / If) และ UPT ถ้าไม่ใช่หญิงวัยเจริญพันธุ์
  void _soAiPick(int fid, {bool quiet = false}) {
    final f = _soFolders().where((x) => x.$1 == fid).firstOrNull;
    if (f == null) return;
    final c = _case;
    var picked = 0, cond = 0, allergy = 0;
    setState(() {
      for (final (name, detail) in f.$3) {
        final id = '${f.$5}$name';
        if (f.$4.contains(id) || _soPrevStatus(name) == 'ทำแล้ว') continue;
        final l = '$name $detail'.toLowerCase();
        if (detail.trimLeft().startsWith('ถ้า') ||
            l.startsWith('stop') ||
            l.startsWith('if ') ||
            detail.contains('ระบุยา')) {
          cond++;
          continue;
        }
        if (name.toUpperCase().contains('UPT') &&
            !(c.sex.contains('หญิง') && c.age >= 12 && c.age <= 50)) {
          cond++;
          continue;
        }
        if (_soCatOfName(name) == 'Medication' && _soAllergyHit(name) != null) {
          allergy++;
          continue;
        }
        f.$4.add(id);
        _soAi.add(id);
        picked++;
      }
    });
    if (quiet) return;
    HapticFeedback.lightImpact();
    _wfToast([
      'AI เลือก $picked รายการ',
      if (cond > 0) 'ข้ามรายการมีเงื่อนไข $cond',
      if (allergy > 0) 'ข้ามยาที่แพ้ $allergy',
    ].join('  '));
  }

  /// เลือกชุดที่ AI แนะนำ: ติ๊กรายการที่เข้ากับเคส (กฎเดียวกับ AI แนะนำในแฟ้ม)
  /// แล้วกรอกรายละเอียดทุกรายการจากข้อมูลเคส · ทุกรายการที่ AI กรอกติดป้าย AI รอแพทย์ยอมรับ
  void _soAiPrefill() {
    final c = _case;
    // คำสั่งนอกชุดที่เหมาะกับเคส: กฎจากข้อมูลจริงของเคส (ค่าที่ใช้ตัดสิน = ที่มา)
    final extra = _soAiExtras();
    // Lab ที่มีในชุดอยู่แล้ว (เทียบรายการตรวจ ไม่ใช่แค่ชื่อบรรทัด) = ไม่แนะนำซ้ำ
    // เช่น ชุดงูกัดมี VCT ในใบ Hematology ของ One Day แล้ว (ประเมินซ้ำตามรอบ progress note)
    // AI ต้องไม่เพิ่ม "VCT ซ้ำทุก 6 ชม." ใน Continuation อีก
    Set<String> testsOf(String line) => {
          ...?_soLabSetOf(line)?.$2,
          if (_soLabSetOf(line) == null) line.trim(),
        };
    bool inSet(String name, String code) {
      final lines = [
        for (final o in _soLinesOf(_template))
          if (!(_soAiWhy[o.$1]?.startsWith('แนะนำเพิ่มนอกชุด') ?? false)) o.$1
      ];
      if (lines.contains(name)) return true;
      if (code != 'L') return false;
      final mine = testsOf(name);
      return lines.any((l) => testsOf(l).any(mine.contains));
    }

    setState(() {
      final ex = _soExtra.putIfAbsent(_template, () => []);
      // ล้างคำแนะนำนอกชุดเดิมที่ซ้ำกับชุด (เคยเพิ่มไว้ก่อนมีการเช็ก)
      ex.removeWhere((o) {
        final dupe =
            (_soAiWhy[o.$1]?.startsWith('แนะนำเพิ่มนอกชุด') ?? false) &&
                inSet(o.$1, o.$3);
        if (dupe) {
          _orderPicked.remove(o.$1);
          _soAiWhy.remove(o.$1);
        }
        return dupe;
      });
      for (final (name, code, oneDay, why) in extra) {
        if (inSet(name, code)) continue;
        if (ex.any((o) => o.$1 == name)) continue;
        ex.add((name, '', code, oneDay));
        _orderPicked.add(name);
        _soAiWhy[name] = 'แนะนำเพิ่มนอกชุด: $why';
      }
    });
    for (final f in _soFolders()) {
      if (f.$1 != 0) _soAiPick(f.$1, quiet: true);
    }
    final hn = _caseP().hn;
    final esi = _caseP().esi?.level ?? 3;
    final pr = _soMaster('er_order_priority');
    // ความเร่งด่วนตาม ESI: 1 = เร่งด่วนที่สุด · 2 = ด่วน · อื่น ๆ = ปกติ
    final urg = pr.isEmpty
        ? null
        : esi <= 1
            ? pr.first
            : esi == 2 && pr.length > 2
                ? pr[1]
                : pr.last;
    final now = DateTime.now();
    final hm =
        '${now.hour.toString().padLeft(2, '0')}:${now.minute.toString().padLeft(2, '0')}';
    final ccRecs = erCcRecords(erCaseOf(hn));
    final dx = [
      for (final d in c.dx) '${d.text}${d.icd10 == null ? '' : ' (${d.icd10})'}'
    ].join(', ');
    final setWhy = _soRecommend()?.$2 ?? 'ตามข้อมูลเคส';
    var n = 0;
    setState(() {
      for (final it in _soDeckItems()) {
        if (it.section == 'Progress Note' || _soDone.contains(it.id)) continue;
        final id = it.id;
        void put(String k, String? v) {
          if (v == null || v.isEmpty) return;
          _soVal.putIfAbsent('$id|$k', () => v);
        }

        switch (_soCatsOf(it).first) {
          case 'Medication':
            final rx = _soParseRx(it.name, it.detail);
            if (_soFieldVal(it, 'ความถี่ยา') == null) {
              put('ความถี่ยา',
                  it.section == 'One Day' ? 'ครั้งเดียว' : 'วันละ 1 ครั้ง');
            }
            if (_soFieldVal(it, 'เวลา') == null) put('เวลา', hm);
            if (_soFieldVal(it, 'จำนวน') == null) {
              put('จำนวน', rx.form == 'fluid' ? '1' : '1');
            }
          case 'Lab':
            put('ความเร่งด่วน', urg);
          case 'X-ray':
            put('ความเร่งด่วน', urg);
            if (ccRecs.isNotEmpty) put('ci', ccRecs.last.text.trim());
            put('cdx', dx);
            put('สภาพผู้ป่วย', c.condition.trim());
          case 'Other':
            // ช่องของรายการอื่น ๆ: ความถี่จากชื่อ (ทุก N ชม.) · รายละเอียด = สิ่งที่ต้องทำ + ที่มา
            for (final f in _soFieldsOf(it)) {
              if (_soFieldVal(it, f.$1) != null) continue;
              if (f.$1 == 'ความถี่') {
                // ตัวเลือกในใบเขียนแบบ "q 2 hr" · ไม่ตรงตัวเลือก = ไม่เลือกให้ (ไม่เดา)
                final m = RegExp(r'ทุก\s*(\d+)\s*ชม').firstMatch(it.name);
                if (m != null) {
                  final want = [
                    'q ${m.group(1)} hr',
                    'ทุก ${m.group(1)} ชั่วโมง',
                  ];
                  put(
                      'ความถี่',
                      f.$2.isEmpty
                          ? want.last
                          : want.where(f.$2.contains).firstOrNull);
                }
              } else if (f.$1 == 'รายละเอียด') {
                put('รายละเอียด', it.name);
              } else if (f.$2.isNotEmpty) {
                put(f.$1, f.$2.first);
              }
            }
          case 'Procedure':
            // ICD-9-CM: ชื่อในชุดไม่ตรง master = จับคำหลัก (ดาม → Splint 93.54)
            if (_soProcVal(it, 'icd') == null) {
              final code = it.name.contains('ดาม') || it.name.contains('เฝือก')
                  ? '93.54'
                  : null;
              for (final x in _procMaster('er_icd9cm')) {
                if (code != null && x.code == code) put('icd', x.name);
              }
            }
            // ผู้ทำ: พยาบาลประจำเตียงที่บันทึกล่าสุด (ไม่มี = พยาบาลคนแรกในทะเบียน)
            if (_soProcLines(it, 'doer').isEmpty) {
              final staff = [for (final x in _procMaster('er_staff')) x.name];
              final rn = [
                for (final r in ccRecs.reversed)
                  if (r.role.contains('พยาบาล')) r.who
              ];
              final first = rn.isEmpty ? '' : rn.first.split(' ').skip(1).first;
              put(
                  'doer',
                  staff
                          .where((n) => first.isNotEmpty && n.contains(first))
                          .firstOrNull ??
                      staff.where((n) => n.startsWith('พย')).firstOrNull);
            }
        }
        _soAi.add(id);
        _soAiWhy.putIfAbsent(
            id, () => 'จาก Standing order $_template ($setWhy)');
        n++;
      }
    });
    HapticFeedback.lightImpact();
    _wfToast(
        'AI เลือกและกรอกให้ $n รายการ (แนะนำเพิ่มนอกชุด ${extra.length}) ตรวจและยอมรับทีละรายการ');
  }

  /// คำสั่งที่ควรเพิ่มนอก Standing order จากข้อมูลเคส: (ชื่อ, ประเภท, One Day?, ที่มา)
  /// ใช้เฉพาะค่าที่มีจริงในเคส (สัญญาณชีพล่าสุด ผล Lab อาการสำคัญ) ไม่เดา
  List<(String, String, bool, String)> _soAiExtras() {
    final c = _case;
    final cc = '${c.cc} ${c.hpi}';
    double? last(List<double> v) => v.isEmpty ? null : v.last;
    final spo2 = last(c.spo2), sbp = last(c.sbp), bt = last(c.bt);
    final hr = last(c.hr);
    final pain = c.painScore ?? 0;
    final glu = c.labs
        .where((l) => l.name == 'Glucose' || l.name == 'DTX')
        .firstOrNull
        ?.value;
    final allergy = c.allergies.join(' ').toLowerCase();
    return [
      if (cc.contains('งู'))
        (
          'VCT 20 นาที ซ้ำทุก 6 ชม.',
          'L',
          false,
          'อาการสำคัญ ${cc.contains('เขียว') ? 'งูเขียวหางไหม้' : 'งู'}กัด เฝ้าระวังเลือดไม่แข็งตัว'
        ),
      if (cc.contains('งู') || cc.contains('บวม'))
        (
          'ยกแขนขาสูง วัดเส้นรอบวงทุก 2 ชม.',
          'oth',
          false,
          'อาการสำคัญ ${cc.contains('บวม') ? 'บวมรอบแผล' : 'ถูกงูกัด'} เฝ้าระวัง compartment syndrome'
        ),
      if (spo2 != null && spo2 < 94)
        (
          'On oxygen cannula 3 L/min',
          'oth',
          true,
          'SpO₂ ล่าสุด ${spo2.round()}%'
        ),
      if (sbp != null && sbp < 90)
        (
          '0.9% NSS 500 mL iv load',
          'M',
          true,
          'SBP ล่าสุด ${sbp.round()} mmHg'
        ),
      if (bt != null && bt >= 38.0)
        ('Hemoculture × 2', 'L', true, 'ไข้ BT ล่าสุด $bt °C'),
      if (hr != null && hr >= 120)
        ('EKG 12 leads', 'ห', true, 'HR ล่าสุด ${hr.round()} /min'),
      if (glu != null && glu > 250)
        ('DTX ทุก 1 ชม.', 'L', false, 'น้ำตาลในเลือด ${glu.round()} mg/dL'),
      if (pain >= 7 && !allergy.contains('morphine'))
        ('Morphine 3 mg iv prn q 4 hr', 'M', false, 'ปวด $pain/10'),
    ];
  }

  /// เพิ่มคำสั่งนอกใบ: ชื่อ + ประเภท → ติ๊กให้แล้วเปิดหน้ากรอกรายละเอียด
  /// เพิ่มคำสั่งนอกเทมเพลตของหมวด: แผ่น filter จาก master (er_order_item_*)
  /// ซ้าย = กลุ่มตามชุดคำสั่ง (Stroke · STEMI · Sepsis ...) · ค้นหาได้ทุกกลุ่ม
  /// ไม่มีในรายการ = "ระบุเอง" (พิมพ์ชื่อ) · เลือกแล้วติ๊กให้และเปิดหน้ากรอกรายละเอียด
  Future<void> _soAddOrder(int fid, {String code0 = 'M'}) async {
    if (code0 == 'L') return _soAddLab(fid);
    final master = switch (code0) {
      'M' => 'er_order_item_med',
      'L' => 'er_order_item_lab',
      'X' => 'er_order_item_xray',
      'ห' => 'er_order_item_procedure',
      _ => 'er_nursing_activity',
    };
    const groups = [
      ('template_general_emergency', 'ฉุกเฉินทั่วไป'),
      ('template_sepsis', 'Sepsis'),
      ('template_stemi', 'STEMI'),
      ('template_stroke', 'Stroke'),
      ('template_trauma', 'Trauma'),
      ('template_non_emergent', 'ตรวจโรคทั่วไป'),
    ];
    final items = [
      for (final x in _procMaster(master))
        if (x.name.trim() != 'อื่นๆ') x
    ];
    List<String> inGroup(String g) => [
          for (final x in items)
            if ((x.extra['templates'] as List?)?.contains(g) ?? false) x.name
        ];
    final cats = <(String, List<String>)>[
      for (final (g, t) in groups)
        if (inGroup(g).isNotEmpty) (t, inGroup(g)),
      // กิจกรรมพยาบาล (master ไม่มีกลุ่ม): จัดหมวดตามรหัส NA ให้หาง่ายแบบแผ่น filter
      if (master == 'er_nursing_activity')
        for (final (t, codes) in const [
          ('เฝ้าระวังอาการ', ['NA01', 'NA07', 'NA09', 'NA17', 'NA18', 'NA12']),
          ('ความปวด', ['NA02', 'NA03', 'NA04', 'NA06']),
          ('ตามแผนการรักษา', ['NA05', 'NA08', 'NA11']),
          ('ดูแลทั่วไป', ['NA10', 'NA13', 'NA14', 'NA15']),
          ('ให้ข้อมูล', ['NA16']),
        ])
          if ([
            for (final x in items)
              if (codes.contains(x.code)) x.name
          ]
              case final xs when xs.isNotEmpty)
            (t, xs),
      // master อื่นที่ไม่มีกลุ่ม = หมวดเดียว · กิจกรรมที่ยังไม่จัดหมวด = อื่น ๆ
      if (master != 'er_nursing_activity' &&
          items.every((x) => x.extra['templates'] == null))
        ('ทั้งหมด', [for (final x in items) x.name]),
      if (master == 'er_nursing_activity')
        if ([
          for (final x in items)
            if (!RegExp(r'^NA(0[1-9]|1[0-8])$').hasMatch(x.code)) x.name
        ]
            case final xs when xs.isNotEmpty)
          ('อื่น ๆ', xs),
    ];
    const types = {
      'M': 'การให้ยา',
      'L': 'Lab',
      'X': 'X-ray',
      'ห': 'หัตถการ',
      'oth': 'อื่น ๆ',
    };
    void add(String n) {
      if (!mounted || n.trim().isEmpty) return;
      setState(() {
        _soExtra
            .putIfAbsent(_template, () => [])
            .add((n.trim(), '', code0, fid != 2));
        _orderPicked.add(n.trim());
      });
      _soEditOpen(n.trim());
    }

    await _soFilterSheet(
      title: 'เพิ่มรายการ${types[code0] ?? ''}',
      sub: 'คำสั่งนอกเทมเพลต ${fid == 2 ? 'Continuation' : 'One Day'}',
      cats: cats,
      current: null,
      // มีในชุดแล้ว (แฟ้มไหนก็ตาม) = จาง "เลือกแล้ว" เลือกซ้ำไม่ได้
      taken: _soNamesInSet(),
      onPick: add,
      customLabel: 'ระบุเอง',
      onCustom: () => _soAddCustom(fid, code0: code0),
    );
  }

  /// เพิ่ม Lab นอกเทมเพลต: ซ้าย = แบบฟอร์ม · ขวา = รายการในฟอร์มนั้น (บอกใบสั่ง + ชุดตรวจ)
  /// เลือกแล้วเปิดใบสั่งของฟอร์มนั้นโดยติ๊กรายการที่เลือกไว้ ติ๊กเพิ่มต่อได้ในใบ
  Future<void> _soAddLab(int fid) async {
    // ค่าในรายการ = ฟอร์ม|ใบ|รายการ (รายการเดียวกันอยู่ได้หลายฟอร์ม)
    String short(String sh) =>
        sh.replaceFirst(RegExp(r'^ใบสั่ง (LAB|Lab) '), '');
    final members = {
      for (final sheets in erLabForms.values)
        for (final (_, ts) in sheets)
          for (final t in ts) t.$1: t.$2.length
    };
    await _soFilterSheet(
      title: 'เพิ่มรายการ Lab',
      sub: 'เลือกแบบฟอร์ม แล้วเลือกรายการในใบ',
      cats: [
        for (final MapEntry(key: f, value: sheets) in erLabForms.entries)
          (
            f,
            [
              for (final (sh, ts) in sheets)
                for (final t in ts) '$f|$sh|${t.$1}',
            ]
          ),
      ],
      current: null,
      taken: {
        for (final MapEntry(key: f, value: sheets) in erLabForms.entries)
          for (final (sh, ts) in sheets)
            for (final t in ts)
              if (_soNamesInSet().contains(t.$1)) '$f|$sh|${t.$1}',
      },
      label: (o) => o.split('|')[2],
      note: (o) {
        final p = o.split('|');
        final n = members[p[2]] ?? 0;
        return [short(p[1]), if (n > 0) 'ชุดตรวจ $n รายการ'].join('  ');
      },
      onPick: (o) {
        if (!mounted) return;
        final p = o.split('|');
        final name = p[2];
        setState(() {
          _soExtra
              .putIfAbsent(_template, () => [])
              .add((name, '', 'L', fid != 2));
          _orderPicked.add(name);
          // ใบสั่งของรายการนี้ = ฟอร์มที่เลือก (ไม่เดาจากชื่อ)
          _soVal['$name|labForm'] = p[0];
          _soVal['$name|labTests'] = name;
        });
        _soEditOpen(name);
      },
      customLabel: 'ระบุเอง',
      onCustom: () => _soAddCustom(fid, code0: 'L'),
    );
  }

  /// ระบุเอง: พิมพ์ชื่อรายการที่ไม่มีใน master
  Future<void> _soAddCustom(int fid, {String code0 = 'M'}) async {
    final name = TextEditingController();
    var code = code0;
    const types = [
      ('M', 'การให้ยา'),
      ('L', 'Lab'),
      ('X', 'X-ray'),
      ('ห', 'หัตถการ'),
      ('oth', 'อื่น ๆ'),
    ];
    // bottom sheet (ย้ายตำแหน่งได้แบบแผ่นอื่น) · หัว = เพิ่มรายการ{หมวด} · ปุ่มหลักเดียว "เพิ่ม"
    String hint(String c) => switch (c) {
          'M' => 'เช่น Ondansetron 4 mg IV stat',
          'L' => 'เช่น Troponin T',
          'X' => 'เช่น CT brain non-contrast',
          'ห' => 'เช่น ใส่สายสวนปัสสาวะ',
          _ => 'เช่น NPO, Record V/S',
        };
    final icon = switch (code) {
      'M' => 'assets/images/er_os_med.png',
      'L' => 'assets/images/er_os_lab.png',
      'X' => 'assets/images/er_os_xray.png',
      'ห' => 'assets/images/er_os_proc_cap.png',
      _ => 'assets/images/er_os_other.png',
    };
    final catName = types.firstWhere((t) => t.$1 == code).$2;
    // bottom sheet (ย้ายตำแหน่งได้): รูปหมวดมุมขวาบน · หัว + คำอธิบาย · ช่องพิมพ์ชื่อ
    // ประเภทมาจากการ์ดหมวดที่กด (ไม่ต้องเลือกซ้ำ) · ปุ่มหลักเดียว "เพิ่ม"
    final ok = await _placedSheet<bool>(
          context: context,
          constraints: const BoxConstraints(maxWidth: 560.0),
          builder: (ctx) => StatefulBuilder(builder: (ctx, setD) {
            final can = name.text.trim().isNotEmpty;
            return Padding(
              padding:
                  EdgeInsets.only(bottom: MediaQuery.of(ctx).viewInsets.bottom),
              child: Container(
                clipBehavior: Clip.antiAlias,
                decoration: const BoxDecoration(
                  color: _panel,
                  borderRadius: BorderRadius.all(Radius.circular(20.0)),
                ),
                child: Stack(children: [
                  Positioned(
                    right: 56.0,
                    top: 10.0,
                    child: IgnorePointer(
                      child: ShaderMask(
                        blendMode: BlendMode.dstIn,
                        shaderCallback: (r) => const LinearGradient(
                          begin: Alignment.topCenter,
                          end: Alignment.bottomCenter,
                          colors: [Colors.white, Colors.transparent],
                          stops: [0.5, 1.0],
                        ).createShader(r),
                        child: Image.asset(icon, width: 64.0, height: 64.0),
                      ),
                    ),
                  ),
                  Padding(
                    padding: const EdgeInsets.fromLTRB(24.0, 20.0, 12.0, 20.0),
                    child: Column(
                        mainAxisSize: MainAxisSize.min,
                        crossAxisAlignment: CrossAxisAlignment.stretch,
                        children: [
                          Row(
                              crossAxisAlignment: CrossAxisAlignment.start,
                              children: [
                                Expanded(
                                  child: Column(
                                      crossAxisAlignment:
                                          CrossAxisAlignment.start,
                                      children: [
                                        Text('เพิ่มรายการ$catName',
                                            style: _t(22.0,
                                                color: _inkTitle,
                                                weight: FontWeight.w700)),
                                        const SizedBox(height: 2.0),
                                        Text(
                                            'คำสั่งนอกเทมเพลต ${fid == 2 ? 'Continuation' : 'One Day'}',
                                            style: _t(13.0,
                                                color: _ink3,
                                                weight: FontWeight.w500)),
                                      ]),
                                ),
                                IconButton(
                                    onPressed: () => Navigator.pop(ctx, false),
                                    icon: const Icon(Icons.close_rounded,
                                        color: _ink2)),
                              ]),
                          const SizedBox(height: 18.0),
                          Padding(
                            padding: const EdgeInsets.only(right: 12.0),
                            child: TextField(
                              controller: name,
                              autofocus: true,
                              textInputAction: TextInputAction.done,
                              onChanged: (_) => setD(() {}),
                              onSubmitted: (_) {
                                if (name.text.trim().isNotEmpty) {
                                  Navigator.pop(ctx, true);
                                }
                              },
                              style: _t(16.0,
                                  color: _inkTitle, weight: FontWeight.w500),
                              decoration: InputDecoration(
                                labelText: 'ชื่อรายการ',
                                labelStyle: _t(14.0,
                                    color: _ink3, weight: FontWeight.w500),
                                floatingLabelStyle: _t(13.0,
                                    color: _blue, weight: FontWeight.w600),
                                hintText: hint(code),
                                hintStyle: _t(14.0, color: _ink3),
                                filled: true,
                                fillColor: _panel,
                                contentPadding: const EdgeInsets.symmetric(
                                    horizontal: 16.0, vertical: 16.0),
                                enabledBorder: OutlineInputBorder(
                                  borderRadius: BorderRadius.circular(14.0),
                                  borderSide: const BorderSide(
                                      color: Color(0xFFDADCE0), width: 0.5),
                                ),
                                focusedBorder: OutlineInputBorder(
                                  borderRadius: BorderRadius.circular(14.0),
                                  borderSide: const BorderSide(
                                      color: _blue, width: 1.0),
                                ),
                              ),
                            ),
                          ),
                          const SizedBox(height: 8.0),
                          Padding(
                            padding: const EdgeInsets.only(left: 4.0),
                            child: Text(
                                'เพิ่มแล้วติ๊กให้ทันที และเปิดหน้ากรอกรายละเอียดต่อ',
                                style: _t(12.5,
                                    color: _ink3, weight: FontWeight.w500)),
                          ),
                          const SizedBox(height: 20.0),
                          Padding(
                            padding: const EdgeInsets.only(right: 12.0),
                            child: AnimatedOpacity(
                              duration: const Duration(milliseconds: 160),
                              opacity: can ? 1.0 : 0.4,
                              child: SizedBox(
                                height: 52.0,
                                child: FilledButton(
                                  style: FilledButton.styleFrom(
                                    backgroundColor: _blue,
                                    disabledBackgroundColor: _blue,
                                    shape: const StadiumBorder(),
                                  ),
                                  onPressed: can
                                      ? () => Navigator.pop(ctx, true)
                                      : null,
                                  child: Text('เพิ่ม',
                                      style: _t(15.0,
                                          color: Colors.white,
                                          weight: FontWeight.w700)),
                                ),
                              ),
                            ),
                          ),
                        ]),
                  ),
                ]),
              ),
            );
          }),
        ) ??
        false;
    final n = name.text.trim();
    // dispose หลังหน้าต่างปิดสุด (ระหว่างแอนิเมชันปิด TextField ยังใช้ controller อยู่)
    Future.delayed(const Duration(milliseconds: 600), name.dispose);
    if (!ok || n.isEmpty || !mounted) return;
    if (_soNamesInSet().contains(n)) {
      _wfToast('$n มีในชุดนี้แล้ว', error: true);
      return;
    }
    setState(() {
      _soExtra.putIfAbsent(_template, () => []).add((n, '', code, fid != 2));
      _orderPicked.add(n);
    });
    _soEditOpen(n);
  }

  /// ชื่อรายการที่อยู่ในชุดนี้แล้ว (ทุกแฟ้ม: ในใบ + ที่เพิ่มนอกเทมเพลต)
  /// รายการเดียวกันอยู่ได้แฟ้มเดียว: One Day กับ Continuation ใช้ชื่อเป็นคีย์ร่วมกัน
  /// (อยู่สองแฟ้ม = ค่าที่กรอก/การติ๊กปนกัน) จึงห้ามเพิ่มซ้ำตั้งแต่ตอนเลือก
  Set<String> _soNamesInSet() => {
        for (final o in _soLinesOf(_template)) o.$1,
        for (final (_, items) in _orderSetPages(_template)) ...items,
      };

  /// ประเภทแรกที่มีรายการในชุดนี้ (ไม่มีเส้นคั่นด้านบน)
  String? _soFirstCat(List<_SoDeckItem> xs) {
    for (final (cat, _, _) in _soCatGroups) {
      if (xs.any((x) => _soCatsOf(x).first == cat)) return cat;
    }
    return null;
  }

  /// ลำดับกลุ่มประเภทในหน้าแฟ้ม: (หมวด, ชื่อ, ไอคอน)
  List<(String, String, String)> get _soCatGroups => const [
        ('Medication', 'การให้ยา', 'assets/images/er_os_med.png'),
        ('Lab', 'Lab', 'assets/images/er_os_lab.png'),
        ('X-ray', 'X-ray', 'assets/images/er_os_xray.png'),
        ('Procedure', 'หัตถการ', 'assets/images/er_os_proc_cap.png'),
        ('Other', 'อื่น ๆ', 'assets/images/er_os_other.png'),
      ];

  /// ประเภทของรายการตามรหัสในใบ (M L X ห) · ชุดไม่มีใบ = ตามชื่อกลุ่มของชุด
  String _soCatOfName(String name) {
    if (_soCats[name] case final c? when c.isNotEmpty) return c.first;
    for (final o in _soLinesOf(_template)) {
      if (o.$1 == name) {
        return switch (o.$3) {
          'M' => 'Medication',
          'L' => 'Lab',
          'X' => 'X-ray',
          'ห' => 'Procedure',
          _ => 'Other',
        };
      }
    }
    for (final (g, items) in _orderSetPages(_template)) {
      if (items.contains(name)) {
        return g.startsWith('ยา')
            ? 'Medication'
            : g.startsWith('แล็บ') || g == 'Lab'
                ? 'Lab'
                : g.startsWith('ภาพ') || g == 'X-ray'
                    ? 'X-ray'
                    : g.startsWith('หัตถการ')
                        ? 'Procedure'
                        : 'Other';
      }
    }
    return 'Other';
  }

  Widget _soDocPage() {
    final folders = _soFolders();
    // -2 = ผู้ใช้หุบทุกใบ · ค่าอื่นที่ไม่มีในชุด = เปิดใบแรก
    final open = _soOpen == -2
        ? -2
        : folders.any((f) => f.$1 == _soOpen)
            ? _soOpen
            : (folders.isEmpty ? -1 : folders.first.$1);
    return Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      mainAxisSize: MainAxisSize.min,
      children: [
        _soSetRow(),
        // แฟ้มแต่ละหมวดเป็นการ์ดขาวแบบแผงวินิจฉัย เปิดได้ทีละใบ (P9)
        for (var i = 0; i < folders.length; i++) ...[
          const SizedBox(height: 12.0),
          _soFolder(folders[i], open == folders[i].$1, i,
              last: i == folders.length - 1),
        ],
      ],
    );
  }

  /// ชุดที่ใช้อยู่: แถวกะทัดรัดแบบรายการ ICD-10 ที่เลือกแล้ว (ไอคอน + ชื่อชุด + จำนวน)
  Widget _soSetRow() => Container(
        padding: const EdgeInsets.fromLTRB(12.0, 12.0, 16.0, 12.0),
        decoration: BoxDecoration(
          color: _panel,
          borderRadius: BorderRadius.circular(16.0),
          border: Border.all(color: const Color(0xFFDADCE0), width: 0.5),
        ),
        child: Row(children: [
          Container(
            width: 36.0,
            height: 36.0,
            decoration:
                const BoxDecoration(color: _blue, shape: BoxShape.circle),
            child: const Icon(Icons.assignment_rounded,
                size: 18.0, color: Colors.white),
          ),
          const SizedBox(width: 12.0),
          Expanded(
            child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                mainAxisSize: MainAxisSize.min,
                children: [
                  Text('Standing order',
                      style: _t(11.5, color: _ink3, weight: FontWeight.w500)),
                  Text(_soFullName[_template] ?? _setName(_template),
                      maxLines: 2,
                      overflow: TextOverflow.ellipsis,
                      style:
                          _t(15.0, color: _inkTitle, weight: FontWeight.w600)),
                ]),
          ),
          const SizedBox(width: 8.0),
          Text('${_soDeckItems().length}',
              style: _num(17.0, color: _inkTitle, weight: FontWeight.w700)),
        ]),
      );

  Widget _soFolder((int, String, List<(String, String)>, Set<String>, String) f,
      bool open, int depth,
      {bool last = false}) {
    final (id, title, items, picks, key) = f;
    final done = items
        .where((it) =>
            picks.contains('$key${it.$1}') ||
            (picks == _soPnPick &&
                _soPnLinked.containsKey(it.$1) &&
                _soLinkedValue(it.$1) != null))
        .length;
    final sub = switch (id) {
      0 => 'ประเมินตามเกณฑ์ของชุด',
      1 => 'ทำครั้งเดียวภายในวันนี้ เช่น เจาะเลือด ถ่ายภาพ ให้ยาครั้งเดียว',
      _ => 'ทำซ้ำตามรอบเวลา จนกว่าแพทย์จะสั่งหยุด',
    };
    // การ์ดขาวขอบบาง มุม 16 (ภาษาเดียวกับ _dxCard) · หัว = ชื่อ + คำอธิบาย + จำนวนที่เลือก
    return Container(
      key: _soFolderKeys.putIfAbsent(id, GlobalKey.new),
      clipBehavior: Clip.antiAlias,
      decoration: BoxDecoration(
        color: _panel,
        borderRadius: BorderRadius.circular(16.0),
        border: Border.all(color: const Color(0xFFDADCE0), width: 0.5),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          InkWell(
            onTap: () {
              HapticFeedback.selectionClick();
              // แตะหัวการ์ดที่เปิดอยู่ = หุบ · การ์ดที่ปิด = เปิด (ใบอื่นหุบ)
              setState(() => _soOpen = open ? -2 : id);
              if (open) return;
              // snap: เลื่อนให้หัวการ์ดที่เปิดชิดบนของแผง (รอการ์ดอื่นหุบก่อน)
              Future.delayed(const Duration(milliseconds: 280), () {
                final c = _soFolderKeys[id]?.currentContext;
                if (c != null && c.mounted) {
                  Scrollable.ensureVisible(c,
                      alignment: 0.0,
                      duration: const Duration(milliseconds: 320),
                      curve: Curves.easeOutCubic);
                }
              });
            },
            child: Padding(
              padding: const EdgeInsets.fromLTRB(16.0, 14.0, 12.0, 14.0),
              child: Row(children: [
                Expanded(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text(title,
                          maxLines: 1,
                          overflow: TextOverflow.ellipsis,
                          style: _t(17.0,
                              color: _inkTitle, weight: FontWeight.w700)),
                      const SizedBox(height: 2.0),
                      Text(sub,
                          style:
                              _t(12.5, color: _ink3, weight: FontWeight.w500)),
                    ],
                  ),
                ),
                Text('$done/${items.length}',
                    style: _num(13.0,
                        color: done == items.length ? _green : _ink2,
                        weight: FontWeight.w600)),
                const SizedBox(width: 6.0),
                AnimatedRotation(
                  turns: open ? 0.5 : 0.0,
                  duration: const Duration(milliseconds: 220),
                  child: const Icon(Icons.keyboard_arrow_down_rounded,
                      size: 22.0, color: _ink3),
                ),
              ]),
            ),
          ),
          AnimatedSize(
            duration: const Duration(milliseconds: 260),
            curve: Curves.easeOutCubic,
            alignment: Alignment.topCenter,
            child: !open
                ? const SizedBox(width: double.infinity)
                : Column(
                    crossAxisAlignment: CrossAxisAlignment.stretch,
                    children: [
                      for (var i = 0; i < items.length; i++) ...[
                        const Divider(
                            height: 1.0,
                            thickness: 0.5,
                            indent: 16.0,
                            endIndent: 16.0,
                            color: Color(0xFFE8EAED)),
                        _soDocRow(items[i], picks, key),
                      ],
                      const SizedBox(height: 6.0),
                    ],
                  ),
          ),
        ],
      ),
    );
  }

  /// แบบฟอร์ม + รายการที่ติ๊กของคำสั่ง Lab: ที่เลือกในใบแล้ว > ชุดคำสั่งตั้งไว้ · null = ไม่รู้
  (String, List<String>)? _soLabSetOf(String name) {
    final n = name.trim();
    final pre = _soLabPreset[n];
    final ts = _soVal['$n|labTests'];
    if (pre == null && ts == null && _soVal['$n|labForm'] == null) return null;
    return (
      _soLabFormOfName(n),
      ts == null
          ? pre?.$2 ?? const []
          : [
              for (final x in ts.split('|'))
                if (x.isNotEmpty) x
            ]
    );
  }

  /// แบบฟอร์ม (บรรทัดบน) แล้วใบสั่งที่จะออก ใบละบรรทัด: ชื่อใบ + รายการที่ติ๊ก
  /// ฟอร์มที่มีใบเดียวชื่อเดียวกัน ไม่บอกชื่อใบซ้ำ
  Widget _soDocLabTree(String form, List<String> picked,
      {bool showForm = true,
      bool boxed = true,
      bool nested = false,
      Color box = _panelSoft}) {
    final sheets = _soLabFormSplit(form, picked.toSet());
    final same = sheets.length == 1 && sheets.first.$1 == form;
    return Padding(
      padding: const EdgeInsets.only(top: 4.0),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          if (showForm)
            Text(form, style: _t(12.0, color: _ink3, weight: FontWeight.w500)),
          // ใบละกล่องพื้นเทาอ่อน ชื่อใบเล็กสีเทาด้านบน รายการต่อกันตัวหนา
          // (ใบเดียวชื่อเดียวกับแบบฟอร์มก็มีกล่อง ให้ทุกการ์ดโครงเดียวกัน)
          // ใบเดียวชื่อเดียวกับแบบฟอร์ม = รายการอย่างเดียว ไม่มีกล่อง
          for (final (k, (sh, xs)) in sheets.indexed)
            if (!boxed)
              // การ์ดซ้าย: ชื่อใบเล็กสีเทา แล้วรายการต่อกันใต้ใบ (ไม่มีกล่อง)
              Padding(
                padding: EdgeInsets.only(top: k == 0 ? 6.0 : 10.0),
                child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      if (!same)
                        Text(sh.replaceFirst(RegExp(r'^ใบสั่ง (LAB|Lab) '), ''),
                            style: _t(12.0,
                                color: _ink3, weight: FontWeight.w600)),
                      Text(xs.map((t) => t.$1).join(', '),
                          style: _t(13.5,
                              color: _ink2,
                              weight: FontWeight.w500,
                              height: 1.4)),
                    ]),
              )
            else
              // กล่องเทาอ่อนต่อใบ: ชื่อใบเล็กสีเทา แล้วรายการต่อกันตัวหนา (ไม่ยาวทีละบรรทัด)
              Container(
                width: double.infinity,
                margin: EdgeInsets.only(top: k == 0 ? 8.0 : 6.0),
                padding: const EdgeInsets.fromLTRB(12.0, 8.0, 12.0, 9.0),
                // nested = การ์ดซ้อนในการ์ด: พื้นเทาจาง ไม่มีเส้นขอบ (กล่องข้อความ: ฟ้าอ่านยาก)
                decoration: BoxDecoration(
                  color: nested ? const Color(0xFFF4F5F7) : box,
                  borderRadius: BorderRadius.circular(10.0),
                ),
                child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text(sh.replaceFirst(RegExp(r'^ใบสั่ง (LAB|Lab) '), ''),
                          style:
                              _t(12.0, color: _ink3, weight: FontWeight.w500)),
                      const SizedBox(height: 2.0),
// โปรไฟล์ละบรรทัด
                      for (final t in xs)
                        Text(t.$1,
                            style: _t(13.5,
                                color: _inkTitle,
                                weight: FontWeight.w600,
                                height: 1.5)),
                    ]),
              ),
        ],
      ),
    );
  }

  Widget _soDocRow((String, String) it, Set<String> picks, String key) {
    final id = '$key${it.$1}';
    final on = picks.contains(id);
    final link = picks == _soPnPick ? _soPnLinked[it.$1] : null;
    if (link != null) return _soLinkedRow(it.$1, link);
    // รายการจากคำสั่งเดิม: ทำแล้ว = ล็อก · ยังไม่ทำ = ยกเลิกได้ (ยืนยันก่อน)
    final prevSt = _soPrevStatus(it.$1);
    final locked = prevSt == 'ทำแล้ว';
    Future<void> toggle() async {
      // เคยสั่งแล้ว: ถามว่าจะสั่งเพิ่มอีกครั้งไหม (ต่อจากรายการเดิมในแผงซ้าย)
      // ยังไม่ทำ = ยกเลิกคำสั่งเดิมได้ด้วย
      if (prevSt != null) {
        final act = await _paperAsk<String>(
          heading: 'สั่งรายการนี้เพิ่มไหม',
          sub: '${it.$1} สั่งไปแล้ว (สถานะ $prevSt)',
          icon: Icons.add_rounded,
          actions: [
            ('สั่งเพิ่ม', 'more', true),
            if (!locked && on) ('ยกเลิกคำสั่งเดิม', 'cancel', false),
            ('ไม่สั่ง', 'no', false),
          ],
        );
        if (!mounted || act == null || act == 'no') return;
        // สั่งเพิ่ม + ยังไม่ได้ติ๊กในแบบร่างนี้ (คำสั่งเดิมอยู่ในครั้งก่อน) = ติ๊กเป็นคำสั่งใหม่ตามปกติ
        // (รายการซ้ำ "สั่งเพิ่ม ครั้งที่ N" ต่อท้ายได้เฉพาะเมื่อรายการเดิมอยู่ในแบบร่างนี้)
        if (act == 'more' && on) {
          HapticFeedback.selectionClick();
          final k = '$_template|${it.$1}';
          final n = (_soMore[k] ?? 0) + 1;
          setState(() => _soMore[k] = n);
          _soEditOpen('${it.$1}#${n + 1}');
          return;
        }
        // act == 'cancel' → ยกเลิกคำสั่งเดิม (เอาติ๊กออกด้านล่าง)
      }
      HapticFeedback.selectionClick();
      setState(() {
        if (on) {
          picks.remove(id);
          _soAi.remove(id);
        } else {
          picks.add(id);
          // ติ๊กแล้วฝั่งซ้ายเปิดการ์ดกรอกรายละเอียดของรายการนั้นทันที
          _soFocus = id;
        }
      });
    }

    // แตะแถว = ติ๊ก/เอาออก (ยังไม่เข้าหน้ากรอก) · รายการที่ติ๊กแล้วมีปุ่ม "ระบุรายละเอียด"
    // แต่ละรายการเป็นการ์ด (น่ากด): ติ๊กแล้ว = พื้นเทาอ่อน · ยังไม่ติ๊ก = ขาวขอบเทา
    // พื้น + ขอบอยู่ที่ Material (ripple วาดบนพื้น ไม่ถูกพื้นขาวทับ)
    // AI แนะนำ (Figma 795:639): ป้ายแคปซูลขาวขอบเทาเกาะมุมซ้ายบนของการ์ด คร่อมขอบบน
    final ai = _soAi.contains(id);
    final row = Padding(
      padding: const EdgeInsets.fromLTRB(8.0, 4.0, 8.0, 4.0),
      child: Material(
        color: _panel,
        shape: RoundedRectangleBorder(
          borderRadius: BorderRadius.circular(14.0),
          side: const BorderSide(color: Color(0xFFDADCE0), width: 0.5),
        ),
        clipBehavior: Clip.antiAlias,
        child: InkWell(
          onTap: toggle,
          splashColor: _blue.withValues(alpha: 0.10),
          highlightColor: _blue.withValues(alpha: 0.04),
          splashFactory: InkRipple.splashFactory,
          child: AnimatedContainer(
            duration: const Duration(milliseconds: 180),
            curve: Curves.easeOut,
            // nested card: กล่องรายการ Lab ห่างขอบการ์ด 8 (น้อยกว่าหัว 14) · หัวเติม padding เอง
            padding: const EdgeInsets.fromLTRB(8.0, 12.0, 8.0, 8.0),
            child: Column(
                crossAxisAlignment: CrossAxisAlignment.stretch,
                children: [
                  // แถวหัว: ชื่อ + วงติ๊กกลางแนวตั้ง (รายการ Lab อยู่ใต้แถวนี้ เต็มความกว้าง)
                  Padding(
                    padding: EdgeInsets.fromLTRB(
                        6.0, 0.0, 4.0, _soLabSetOf(it.$1) == null ? 4.0 : 0.0),
                    child: Row(children: [
                      Expanded(
                        child: Column(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            Row(children: [
                              // Lab: หัวใหญ่สุด = ชื่อแบบฟอร์ม (ใบสั่ง → รายการอยู่ใต้)
                              // ป้ายเล็กจาง "ชื่อแบบฟอร์ม" เหนือชื่อ (บอกว่าหัวนี้คืออะไร)
                              Flexible(
                                child: Column(
                                    crossAxisAlignment:
                                        CrossAxisAlignment.start,
                                    mainAxisSize: MainAxisSize.min,
                                    children: [
                                      if (_soLabSetOf(it.$1) != null)
                                        Text('ชื่อแบบฟอร์ม',
                                            style: _t(11.5,
                                                color: _ink3,
                                                weight: FontWeight.w500)),
                                      Text(_soLabSetOf(it.$1)?.$1 ?? it.$1,
                                          maxLines: 1,
                                          overflow: TextOverflow.ellipsis,
                                          style: _t(14.0,
                                              color: _inkTitle,
                                              weight: FontWeight.w600)),
                                    ]),
                              ),
                              // ยา STAT: ป้ายด่วนแบบงานด่วนในการ์ดคำสั่งแพทย์
                              if (on && _soStat(id)) ...[
                                const SizedBox(width: 6.0),
                                _soStatBadge(),
                              ],
                              // Dr.Note กรอกให้ รอแพทย์ยอมรับ
                              // ไม่แสดงสถานะคำสั่งเดิม (รอรับ ทำแล้ว ใหม่) ในแถวเลือก: ดูที่ประวัติคำสั่ง
                            ]),
                            if (_soLabSetOf(it.$1) == null && it.$2.isNotEmpty)
                              Text(it.$2, style: _t(12.0, color: _ink3)),
                            // รายละเอียดที่กรอกไม่ซ้ำที่นี่: แผงซ้ายแสดงอยู่แล้ว
                          ],
                        ),
                      ),
                      // ไม่มีลูกศร: เข้าหน้ากรอกจากแถวในแบบร่างฝั่งซ้าย
                      const SizedBox(width: 4.0),
                      GestureDetector(
                          behavior: HitTestBehavior.opaque,
                          onTap: toggle,
                          child: Padding(
                              padding: const EdgeInsets.all(6.0),
                              // แถวถูกสร้างใหม่ตอนติ๊ก (animation แบบ implicit ไม่เล่น) จึงจำสถานะเดิมตาม id
                              child: _SoCheck(
                                  id: id,
                                  on: on,
                                  color: locked ? _ink3 : _blue))),
                    ]),
                  ),
                  // Lab: ใบสั่ง → รายการ เต็มความกว้างการ์ด (ใต้หัว + วงติ๊ก) · การ์ดซ้อน = พื้น surface
                  if (_soLabSetOf(it.$1) case (final form, final ts))
                    _soDocLabTree(form, ts, showForm: false, nested: true),
                ]),
          ),
        ),
      ),
    );
    if (!ai) return row;
    return Padding(
      padding: const EdgeInsets.only(top: 10.0),
      child: Stack(clipBehavior: Clip.none, children: [
        row,
        // เยื้องเข้าจากขอบซ้ายการ์ด (ไม่ชิดมุม) · ตัวเล็กกว่าชื่อรายการชัด
        Positioned(
          left: 22.0,
          top: -7.0,
          child: Container(
            // สี AI ของแอป (ไล่ฟ้า → ม่วง แบบป้าย AI อื่น) ขอบขาวแบบสติกเกอร์บนขอบการ์ด
            padding: const EdgeInsets.fromLTRB(7.0, 2.0, 8.0, 2.0),
            decoration: BoxDecoration(
              gradient: const LinearGradient(
                  colors: [Color(0xFF4F46E5), Color(0xFF9333EA)]),
              borderRadius: BorderRadius.circular(16.0),
              border: Border.all(color: Colors.white, width: 1.5),
            ),
            child: Row(mainAxisSize: MainAxisSize.min, children: [
              const Icon(Icons.auto_awesome_rounded,
                  size: 10.0, color: Colors.white),
              const SizedBox(width: 3.0),
              Text('AI แนะนำ',
                  style:
                      _t(10.5, color: Colors.white, weight: FontWeight.w600)),
            ]),
          ),
        ),
      ]),
    );
  }
}

/// การ์ดหนึ่งใบในสำรับฝั่งซ้าย
class _SoDeckItem {
  const _SoDeckItem(this.id, this.name, this.section, this.cat, this.tone,
      [this.detail = '', this.at, this.done]);

  /// ประวัติ: ทำแล้วโดยใคร เมื่อไร (แถบรอบ = รอบแรกทำแล้ว รอบถัดไปนับต่อ)
  final (String, DateTime)? done;

  /// เวลาที่สั่ง (คำสั่งที่บันทึกแล้ว): แถบรอบเริ่มนับจากเวลานี้ ไม่ใช่ "ตอนนี้" · null = แบบร่าง
  final DateTime? at;
  final String id;
  final String name;

  /// รายละเอียดบรรทัดในใบ (คำอธิบายใต้ชื่อ)
  final String detail;

  /// แฟ้มที่อยู่: Progress Note / One Day / Continuation
  final String section;

  /// หมวดเริ่มต้นตามรหัสในใบ (Lab, Procedure, X-ray, Medication, Other)
  final String cat;

  /// สีหัวการ์ด = สีแฟ้มที่รายการนี้อยู่ในแผงขวา
  final Color tone;
}

/// คำสั่ง Lab ในชุดคำสั่งจำลอง → (แบบฟอร์ม, รายการที่ติ๊กในใบ) โครงเดียวกับตอนสั่ง
/// ทุกรายการต้องมีในแบบฟอร์มนั้น (ไม่หายเงียบ เช่น antiHIV = VCT ในใบ Hematology)
