  Widget _soHero() {
    final pending = _soAi.length;
    final title = _soAiBusy
        ? 'AI กำลังอ่านข้อมูลเคส'
        : pending > 0
            ? 'กรอกให้แล้ว รอตรวจ $pending รายการ'
