Set<String> _soGuessCats(String text) {
  final t = ' ${text.toLowerCase()} ';
  final got = {
    for (final e in _soCatWords.entries)
      if (e.value.any(t.contains)) e.key,
    // ขนาดยา เช่น 500 mg, 4.5 g, 30 ml/kg (ไม่นับหน่วยผล เช่น DTX mg/dl)
    if (RegExp(r'\d\s?(mg|g|ml/kg|mcg)\b(?!/dl)').hasMatch(t)) 'Medication',
  };
  return got.isEmpty ? {'Other'} : got;
}

extension _SoStructPart on _ErFlowHomeWidgetState {
  /// หมวดปัจจุบันของบรรทัด: ที่แก้เอง > ที่ทีมกำกับหลายหมวด > รหัสในใบ
  Set<String> _soCatsFor(String name, String code) =>
      _soCats[name] ??
      _soCatMulti[name] ??
      {
        for (final d in _soCatDefs)
          if (d.$2 == code) d.$1
      };

  /// หน้าตั้งค่า Standing order (ยกเครื่อง 2026-11-05): อ่านง่าย ใช้ง่าย
  /// บน = ชื่อหน้า + จำแนกอัตโนมัติ · เลือกใบ (แท็บ) · กรองตามหมวด (ชิปนับจำนวน แตะ = กรอง)
  /// รายการ = การ์ดแยกตาม One Day / Continuation · แต่ละแถว: ชื่อบรรทัด + รายละเอียด
  /// ขวา = หมวด (ป้ายชื่อเต็ม + ไอคอน แตะ = แผ่นเลือกหมวด) · ล่าง = ฟอร์มบันทึกผล (เฉพาะหัตถการ/อื่น ๆ)
  Widget _soStructView(String cur, ValueChanged<String> onPick,
      Set<String> changed, StateSetter setSheet) {
    void upd(VoidCallback f) {
      setState(f);
      setSheet(() {});
    }

    // บรรทัดเดิมของชุด + ที่เพิ่มเอง (_soExtra ชุดเดียวกับที่หน้าสั่งการรักษาใช้)
    final doc = [...?_soStructDocs[cur], ...?_soExtra[cur]];
    final filter = _soStructFilter;
    final counts = {
      for (final d in _soCatDefs)
        d.$1: doc.where((o) => _soCatsFor(o.$1, o.$3).contains(d.$1)).length
    };
    String th(String c) => switch (c) {
          'Lab' => 'Lab',
          'X-ray' => 'X-ray',
          'Medication' => 'ยา',
          'Procedure' => 'หัตถการ',
          _ => 'อื่น ๆ',
        };
    // รูปหมวดชุดเดียวกับหน้าคำสั่งแพทย์
    Widget art(String c, double size) =>
        Image.asset(_soCatGroups.firstWhere((g) => g.$1 == c).$3,
            width: size,
            height: size,
            fit: BoxFit.contain,
            filterQuality: FilterQuality.medium);

    // แผ่นเลือกหมวด (เลือกได้หลายหมวด ต้องเหลืออย่างน้อย 1)
    Future<void> pickCats((String, String, String, bool) o) =>
        _placedSheet<void>(
          context: context,
          constraints: const BoxConstraints(maxWidth: 480.0),
          builder: (ctx) => StatefulBuilder(builder: (ctx, setS) {
            final on = _soCatsFor(o.$1, o.$3);
            return Container(
              padding: const EdgeInsets.fromLTRB(20.0, 20.0, 20.0, 16.0),
              decoration: BoxDecoration(
                  color: _panel, borderRadius: BorderRadius.circular(20.0)),
              child: Column(
                  mainAxisSize: MainAxisSize.min,
                  crossAxisAlignment: CrossAxisAlignment.stretch,
                  children: [
                    Text('หมวดของรายการ',
                        style: _t(18.0,
                            color: _inkTitle, weight: FontWeight.w700)),
                    Text(o.$1,
                        style: _t(14.0, color: _ink2, weight: FontWeight.w500)),
                    const SizedBox(height: 4.0),
                    Text('เลือกได้มากกว่า 1 หมวด',
                        style: _t(12.5, color: _ink3, weight: FontWeight.w500)),
                    const SizedBox(height: 12.0),
                    for (final (i, d) in _soCatDefs.indexed) ...[
                      if (i > 0)
                        const Divider(
                            height: 1.0,
                            thickness: 1.0,
                            color: Color(0xFFE8EAED)),
                      InkWell(
                        onTap: () {
                          final next = {...on};
                          if (next.contains(d.$1)) {
                            if (next.length == 1) return;
                            next.remove(d.$1);
                          } else {
                            next.add(d.$1);
                          }
                          HapticFeedback.selectionClick();
                          upd(() {
                            _soCats[o.$1] = next;
                            changed.remove(o.$1);
                          });
                          setS(() {});
                        },
                        child: Padding(
                          padding: const EdgeInsets.symmetric(vertical: 12.0),
                          child: Row(children: [
                            art(d.$1, 32.0),
                            const SizedBox(width: 14.0),
                            Expanded(
                              child: Text(th(d.$1),
                                  style: _t(15.0,
                                      color: _inkTitle,
                                      weight: FontWeight.w600)),
                            ),
                            Icon(
                                on.contains(d.$1)
                                    ? Icons.check_box_rounded
                                    : Icons.check_box_outline_blank_rounded,
                                size: 24.0,
                                color: on.contains(d.$1) ? _blue : _ink3),
                          ]),
                        ),
                      ),
                    ],
                  ]),
            );
          }),
        );

    // แผ่นเพิ่มบรรทัดในชุดนี้ ลงแฟ้ม One Day / Continuation ตามการ์ดที่กด
    Future<void> addLine(bool one) async {
      final nameCtl = TextEditingController(),
          detailCtl = TextEditingController();
      var cat = filter ?? 'Other';
      var picked = filter != null;
      String? err;
      InputDecoration dec(String label) {
        OutlineInputBorder b(Color c, double w) => OutlineInputBorder(
            borderRadius: BorderRadius.circular(8.0),
            borderSide: BorderSide(color: c, width: w));
        return InputDecoration(
          labelText: label,
          labelStyle: _t(14.0, color: _ink2, weight: FontWeight.w500),
          contentPadding:
              const EdgeInsets.symmetric(horizontal: 14.0, vertical: 15.0),
          enabledBorder: b(_ink3, 1.0),
          focusedBorder: b(_blue, 2.0),
        );
      }

      final added = await _placedSheet<String>(
        context: context,
        constraints: const BoxConstraints(maxWidth: 480.0),
        builder: (ctx) => StatefulBuilder(builder: (ctx, setS) {
          void save() {
            final n = nameCtl.text.trim();
            if (n.isEmpty) return setS(() => err = 'ตั้งชื่อรายการก่อน');
            if (doc.any((o) => o.$1.trim() == n)) {
              return setS(() => err = 'ชุดนี้มีรายการนี้แล้ว');
            }
            final code = _soCatDefs.firstWhere((d) => d.$1 == cat).$2;
            upd(() {
              _soExtra
                  .putIfAbsent(cur, () => [])
                  .add((n, detailCtl.text.trim(), code, one));
              _soCats[n] = {cat};
            });
            Navigator.pop(ctx, n);
          }

          return Container(
            padding: const EdgeInsets.fromLTRB(20.0, 20.0, 20.0, 16.0),
            decoration: BoxDecoration(
                color: _panel, borderRadius: BorderRadius.circular(20.0)),
            child: Column(
                mainAxisSize: MainAxisSize.min,
                crossAxisAlignment: CrossAxisAlignment.stretch,
                children: [
                  Text('เพิ่มรายการ',
                      style:
                          _t(18.0, color: _inkTitle, weight: FontWeight.w700)),
                  Text('$cur ${one ? 'Order for One Day' : 'Continuation'}',
                      style: _t(14.0, color: _ink2, weight: FontWeight.w500)),
                  const SizedBox(height: 16.0),
                  TextField(
                    controller: nameCtl,
                    autofocus: true,
                    onChanged: (v) => setS(() {
                      err = null;
                      // ยังไม่ได้เลือกเอง: เดาหมวดจากชื่อ
                      if (!picked && v.trim().isNotEmpty) {
                        cat = _soGuessCats(v).first;
                      }
                    }),
                    style: _t(15.0, color: _inkTitle, weight: FontWeight.w600),
                    decoration: dec('ชื่อรายการ'),
                  ),
                  if (err != null)
                    Padding(
                      padding: const EdgeInsets.only(top: 6.0),
                      child: Text(err!,
                          style:
                              _t(12.5, color: _red, weight: FontWeight.w600)),
                    ),
                  const SizedBox(height: 14.0),
                  TextField(
                    controller: detailCtl,
                    style: _t(15.0, color: _inkTitle, weight: FontWeight.w600),
                    decoration: dec('รายละเอียด (ไม่บังคับ)'),
                  ),
                  const SizedBox(height: 16.0),
                  Text('หมวด',
                      style: _t(13.0, color: _ink2, weight: FontWeight.w500)),
                  const SizedBox(height: 8.0),
                  Wrap(spacing: 8.0, runSpacing: 8.0, children: [
                    for (final d in _soCatDefs)
                      ChoiceChip(
                        avatar: art(d.$1, 20.0),
                        label: Text(th(d.$1)),
                        selected: cat == d.$1,
                        showCheckmark: false,
                        labelStyle: _t(13.5,
                            color: cat == d.$1 ? _blue : _inkTitle,
                            weight: FontWeight.w600),
                        selectedColor: _blue.withValues(alpha: 0.08),
                        backgroundColor: _panel,
                        side: BorderSide(
                            color: cat == d.$1
                                ? Colors.transparent
                                : const Color(0xFFDADCE0)),
                        shape: const StadiumBorder(),
                        onSelected: (_) => setS(() {
                          cat = d.$1;
                          picked = true;
                        }),
                      ),
                  ]),
                  const SizedBox(height: 20.0),
                  FilledButton(
                    onPressed: save,
                    style: FilledButton.styleFrom(
                      backgroundColor: _blue,
                      foregroundColor: Colors.white,
                      minimumSize: const Size.fromHeight(48.0),
                      shape: const StadiumBorder(),
                      textStyle: _t(14.0, weight: FontWeight.w600),
                    ),
                    child: const Text('เพิ่มรายการ'),
                  ),
                ]),
          );
        }),
      );
      // ปิดหลังแผ่นเลื่อนลงจบ
      Future<void>.delayed(const Duration(seconds: 1), () {
        nameCtl.dispose();
        detailCtl.dispose();
      });
      if (added == null || !mounted) return;
      HapticFeedback.mediumImpact();
      late final OverlayEntry toast;
      toast = OverlayEntry(
          builder: (_) => _SoSavedToast(
              text: 'เพิ่ม $added แล้ว',
              style: _t(14.0, color: Colors.white, weight: FontWeight.w600),
              onEnd: () => toast.remove()));
      Overlay.of(context, rootOverlay: true).insert(toast);
    }

    // ลบได้เฉพาะบรรทัดที่เพิ่มเอง (บรรทัดต้นฉบับของชุดคำสั่งลบไม่ได้)
    Future<void> removeLine((String, String, String, bool) o) async {
      final ok = await _paperAsk<bool>(
        heading: 'ลบรายการ "${o.$1}"',
        sub: 'รายการนี้จะหายจากชุดคำสั่ง $cur',
        actions: const [('ยกเลิก', false, false), ('ลบ', true, true)],
      );
      if (ok != true) return;
      upd(() {
        _soExtra[cur]?.remove(o);
        _soCats.remove(o.$1);
      });
    }

