/// ช่องต้นทางของแผ่นพิมพ์ที่เปิดอยู่ (ช่องนั้นขึ้นสถานะ "กำลังแก้")
final ValueNotifier<RenderBox?> _ftActive = ValueNotifier(null);

/// context ของช่องข้อความอิสระที่กำลังสร้าง (ใช้เป็นต้นทางของแผ่นพิมพ์)
BuildContext? _ftOriginCtx;

/// ตำแหน่งบรรทัดข้อความในช่องพิมพ์ของแผ่นเต็ม (จากขอบบนแผ่น) ใช้เป็นปลายทางข้อความที่บินมา
const double _ftInputTop = 74.0;

/// บันทึกแผ่นพิมพ์ที่เปิดค้างทันที (เรียกตอนเปลี่ยนหน้า) · null = ไม่มีแผ่นเปิด
VoidCallback? _ftCommit;

/// "3 พ.ย." (ใส่ปี พ.ศ. ถ้าคนละปีกับวันนี้)
String _ftDateTh(DateTime d) {
  const m = [
    'ม.ค.', 'ก.พ.', 'มี.ค.', 'เม.ย.', 'พ.ค.', 'มิ.ย.', //
    'ก.ค.', 'ส.ค.', 'ก.ย.', 'ต.ค.', 'พ.ย.', 'ธ.ค.'
  ];
  final n = DateTime.now();
  return '${d.day} ${m[d.month - 1]}${d.year != n.year ? ' ${d.year + 543}' : ''}';
}

/// "พรุ่งนี้ 3 พ.ย." (คำบอกวัน + วันที่ย่อ พ.ศ. ไม่ใส่ปีถ้าปีเดียวกัน)
String _ftTomorrow() {
  const m = [
    'ม.ค.', 'ก.พ.', 'มี.ค.', 'เม.ย.', 'พ.ค.', 'มิ.ย.', //
    'ก.ค.', 'ส.ค.', 'ก.ย.', 'ต.ค.', 'พ.ย.', 'ธ.ค.'
  ];
  final n = DateTime.now();
  final d = DateTime(n.year, n.month, n.day + 1);
  return 'พรุ่งนี้ ${d.day} ${m[d.month - 1]}${d.year != n.year ? ' ${d.year + 543}' : ''}';
}

/// ข้อความเวลาที่ขึ้นต้นด้วย "พรุ่งนี้" = ตัดคำนำออก เหลือวันที่ + เวลา (ไม่มี badge)
// ignore: avoid_unused_parameters
Widget _ftDayText(String text, TextStyle style, TextStyle badge) {
  final rest =
      text.startsWith('พรุ่งนี้ ') ? text.substring('พรุ่งนี้ '.length) : text;
  return Text(rest, maxLines: 1, overflow: TextOverflow.ellipsis, style: style);
}

/// นาทีในวัน → เวลาจริงนับจากตอนนี้ (ก่อนเวลาปัจจุบัน = พรุ่งนี้ +1440)
// ignore: unused_element
int _ftEff(int m, int now) => m < now ? m + 1440 : m;

/// เวลาจริงของครั้งที่ k ตามลำดับ: นับต่อจากครั้งก่อนหน้า (ครั้งแรกนับจากตอนนี้)
/// เช่น ครั้งที่ 1 = พรุ่งนี้ 09:00 แล้วครั้งที่ 2 เลือก 21:00 = พรุ่งนี้ 21:00 (ไม่ใช่วันนี้)
int _ftAfter(int m, int base) {
  var e = m;
  while (e <= base) {
    e += 1440;
  }
  return e;
}

/// เวลาจริง (นาทีนับจากเที่ยงคืนวันนี้) ของทุกครั้งตามลำดับ · ช่องว่าง = null (ข้ามไป)
List<int?> _ftEffs(List<int?> slots, int now) {
  var base = now - 1;
  return [
    for (final m in slots)
      if (m == null)
        null
      else
        () {
          base = _ftAfter(m, base);
          return base;
        }()
  ];
}

/// ความสูงแถบย่อ (notch ชิดขอบล่างจอ)
const double _ftNotchH = 42.0;

/// แผ่นพิมพ์ที่เปิดอยู่ (เปิดได้ทีละแผ่น: เปิดแผ่นใหม่ = ปิดแผ่นเดิมแบบไม่บันทึก)
void Function(String?)? _ftCloser;

/// แผ่นพิมพ์ข้อความอิสระ ใช้ได้จากทุกที่ที่มี context (รวม widget นอก state หลัก)
/// ลอยบน overlay ไม่มีฉากมืด: ข้างหลังยังเลื่อนอ่าน/แตะได้ระหว่างพิมพ์
/// ไอคอนไมค์มีสถานะ (ภาพอ้างอิงผู้ใช้ 2026-11-03): วาดเอง หัวไมค์เติมเขียวจากล่างขึ้นตามเสียง
class _FtMic extends StatefulWidget {
  const _FtMic({required this.state, this.size = 24.0});
  final ErSpeechState state;
  final double size;
  @override
  State<_FtMic> createState() => _FtMicState();
}

class _FtMicState extends State<_FtMic> with SingleTickerProviderStateMixin {
  // ระดับที่วาด ไล่ตามระดับเสียงจริงนุ่ม ๆ ทุกเฟรม · ถอดเสียง = กะพริบ
  late final AnimationController _t =
      AnimationController(vsync: this, duration: const Duration(seconds: 1))
        ..repeat();
  double _lv = 0.0;

  @override
  void dispose() {
    _t.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) => AnimatedBuilder(
        animation: _t,
        builder: (context, _) {
          final st = widget.state;
          final off =
              st == ErSpeechState.permissionDenied || st == ErSpeechState.error;
          final listen = st == ErSpeechState.listening;
          final proc =
              st == ErSpeechState.processing || st == ErSpeechState.permission;
          final target = listen
              ? 0.18 + 0.82 * erMicLevel.value
              : proc
                  ? 1.0
                  : 0.0;
          _lv += (target - _lv) * 0.25;
          final pulse = proc
              ? 0.55 + 0.45 * (0.5 + 0.5 * math.cos(_t.value * 2 * math.pi))
              : 1.0;
          return CustomPaint(
            size: Size.square(widget.size),
            painter: _FtMicPainter(
                fill: _lv, off: off, on: listen || proc, alpha: pulse),
          );
        },
      );
}

class _FtMicPainter extends CustomPainter {
  _FtMicPainter(
      {required this.fill,
      required this.off,
      required this.on,
      required this.alpha});
  final double fill;
  final bool off, on;
  final double alpha;
  static const _g = Color(0xFF0F9D58), _dark = Color(0xFF4A4F57);
  static const _grey = Color(0xFFC4C7CC), _red = Color(0xFFE53935);

  @override
  void paint(Canvas c, Size s) {
    final w = s.width, h = s.height;
    final head = RRect.fromRectAndRadius(
        Rect.fromLTWH(w * 0.34, h * 0.06, w * 0.32, h * 0.52),
        Radius.circular(w * 0.16));
    final base = off ? _grey : (on ? _g : _dark);
    // หัวไมค์: พื้นเทาเข้ม แล้วเติมเขียวจากล่างตามระดับ
    c.drawRRect(head, Paint()..color = off ? _grey : _dark);
    if (!off && fill > 0.001) {
      c.save();
      c.clipRRect(head);
      final top = head.bottom - head.height * fill.clamp(0.0, 1.0);
      c.drawRect(Rect.fromLTRB(head.left, top, head.right, head.bottom),
          Paint()..color = _g.withValues(alpha: alpha));
      c.restore();
    }
    // ขาไมค์: โค้ง U + ก้าน + ฐาน
    final p = Paint()
      ..color = base
      ..style = PaintingStyle.stroke
      ..strokeWidth = w * 0.085
      ..strokeCap = StrokeCap.round;
    c.drawArc(Rect.fromLTWH(w * 0.22, h * 0.22, w * 0.56, h * 0.5), 0.15,
        math.pi - 0.3, false, p);
    c.drawLine(Offset(w * 0.5, h * 0.73), Offset(w * 0.5, h * 0.86), p);
    c.drawLine(Offset(w * 0.36, h * 0.88), Offset(w * 0.64, h * 0.88), p);
    // ใช้ไม่ได้: ขีดแดงทแยง
    if (off) {
      c.drawLine(
          Offset(w * 0.2, h * 0.12),
          Offset(w * 0.82, h * 0.8),
          Paint()
            ..color = _red
            ..strokeWidth = w * 0.09
            ..strokeCap = StrokeCap.round);
    }
  }

  @override
  bool shouldRepaint(_FtMicPainter o) =>
      o.fill != fill || o.off != off || o.on != on || o.alpha != alpha;
}

/// คำขอเปิดหน้าย่อยพิมพ์ข้อความใน workflow panel (แทนแผ่นพิมพ์ลอย สำหรับช่องใน workflow)
class _WfText {
  _WfText(
      {required this.title,
      this.sub,
      required this.initial,
      required this.hint,
      this.aiRun,
      this.aiPanel,
      this.aiLabel,
      this.extra,
      this.aiConfirm});

  /// ถามก่อนเปิดข้อเสนอ AI (มีข้อมูลเดิมที่จะถูกแทนที่) · false = ไม่เปิด
  final Future<bool> Function(String text)? aiConfirm;

  /// ส่วนเสริมใต้ช่องพิมพ์ (เช่น เลือกรหัส ICD-10 ของคำวินิจฉัยนี้) · rebuild = วาดหน้าใหม่
  final Widget Function(VoidCallback rebuild)? extra;

  /// ชื่อปุ่ม AI (null = "กรอกอัตโนมัติ")
  final String? aiLabel;
  final String title;
  final String? sub;
  final String initial;
  final String hint;
  final Future<_FtAiOut?> Function(String text)? aiRun;

  /// ข้อเสนอ AI แบบเลือก (เช่น Dr.Note เสนอโรค): แสดงแทนที่ในการ์ดข้อความ
  /// เลือกแล้วเรียก done(ผล) = เติมลงช่อง · done(null) = กลับไปหน้าพิมพ์
  final Widget Function(void Function(_FtAiOut?) done)? aiPanel;
  final Completer<String?> done = Completer<String?>();
}

/// ยืนยันลบข้อมูลช่อง (bottom sheet) · แผง workflow ตั้งค่าให้ตอนวาด
Future<bool> Function(String title)? _wfConfirmDelete;

/// ยืนยันแทนที่ข้อมูลด้วยข้อเสนอ AI (dialog กระดาษ) · แผง workflow ตั้งค่าให้
Future<bool> Function(String title)? _wfConfirmReplaceAi;

/// หน้าย่อยพิมพ์ที่เปิดอยู่ใน workflow panel (null = ไม่มี) · แผง workflow วาดใหม่ผ่าน [_wfTextRebuild]
_WfText? _wfText;
VoidCallback? _wfTextRebuild;

/// ปิดหน้าย่อยพิมพ์ (ส่งผล v = บันทึก · null = ยกเลิก)
void _wfTextClose(String? v) {
  final r = _wfText;
  if (r == null) return;
  _wfText = null;
  if (_ftCommit == _wfTextCommit) _ftCommit = null;
  if (!r.done.isCompleted) r.done.complete(v);
  _wfTextRebuild?.call();
}

/// ไปหน้าอื่นของ workflow ระหว่างพิมพ์ = บันทึกข้อความล่าสุดแล้วปิด (แบบแผ่นลอยเดิม)
String Function()? _wfTextValue;

/// ต่อท้ายข้อความในหน้าพิมพ์ที่เปิดอยู่ (บรรทัดใหม่) · Re-Diag กดเพิ่มระหว่างพิมพ์ Diagnosis Text
void Function(String line)? _ftAppendLine;
void _wfTextCommit() {
  // ไปหน้าอื่นทั้งที่ลบจนว่าง = ไม่ลบเงียบ ๆ (การลบต้องกดบันทึกแล้วยืนยันเท่านั้น)
  final v = _wfTextValue?.call().trim();
  final r = _wfText;
  _wfTextClose(
      v != null && v.isEmpty && r != null && r.initial.trim().isNotEmpty
          ? null
          : v);
}

/// หน้าย่อยพิมพ์ข้อความใน workflow panel (โครงเดียวกับแผ่นพิมพ์ลอย):
/// หัว + คำอธิบาย + ปุ่มกรอกอัตโนมัติ → กล่องพิมพ์ (nested card สูงเต็มที่เหลือ) → แหล่งที่มา
/// → footer [ยกเลิก] ไมค์ [บันทึก]
class _FtPage extends StatefulWidget {
  const _FtPage({super.key, required this.req});
  final _WfText req;
  @override
  State<_FtPage> createState() => _FtPageState();
}

class _FtPageState extends State<_FtPage> with TickerProviderStateMixin {
  late final _ct = _FtHiController(text: widget.req.initial);
  final _focus = FocusNode();
  final _sp = ErSpeechInput();

  /// ให้ _runAi ที่คัดลอกจากแผ่นลอยเรียกผ่าน widget.aiRun ได้ตรงตัว
  _WfText get _w => widget.req;

  /// สีเขียวของข้อความที่ AI เติม: 1 = เขียวเต็ม → ค้างครู่หนึ่งแล้วค่อยจางกลับเป็นสีปกติ
  late final AnimationController _glow = AnimationController(
      vsync: this, duration: const Duration(milliseconds: 3000))
    ..addListener(() {
      final v = _glow.value;
      // 0–45% ค้างเขียว · 45–100% จางออกนุ่ม
      _ct.setGlow(v < 0.45
          ? 1.0
          : 1.0 - Curves.easeInOutCubic.transform((v - 0.45) / 0.55));
    });

  /// เรื่องเล่าตอน AI กรอก: (1) ช่อง [คำใบ้] หายไปพร้อมกัน ข้อความเดิมคงที่
  /// (2) ข้อความใหม่พิมพ์ไหลลงทีละช่อง ไล่จากบนลงล่าง เป็นสีเขียว (เหมือนมีคนกรอกให้)
  /// (3) กรอกครบ = ชิปแหล่งที่มาโผล่ (บอกว่าเอามาจากไหน) (4) เขียวค้างครู่หนึ่งแล้วจางเป็นสีปกติ
  late final AnimationController _rv = AnimationController(vsync: this);
  List<TextRange> _rvHi = const [];
  String _rvText = '';
  VoidCallback? _rvTick;

  void _playFill(String before, String t, List<(String, String)> refs) {
    _glow.stop();
    _rv.stop();
    _aiRefs = const [];
    final hi = _ftInserted(before, t);
    final total = hi.fold<int>(0, (n, r) => n + (r.end - r.start));
    _rvHi = hi;
    _rvText = t;
    _ct.setGlow(1.0);
    void apply(int shown) {
      // ข้อความที่แสดง = ข้อความใหม่ แต่ส่วนที่เติมยังไม่ถึงคิว ตัดออก
      final out = StringBuffer();
      final ranges = <TextRange>[];
      var left = shown, at = 0;
      for (final h in hi) {
        out.write(t.substring(at, h.start));
        final take = math.min(left, h.end - h.start);
        if (take > 0) {
          final st = out.length;
          out.write(t.substring(h.start, h.start + take));
          ranges.add(TextRange(start: st, end: out.length));
        }
        left -= take;
        at = h.end;
      }
      out.write(t.substring(at));
      final txt = out.toString();
      _ct.hi = ranges;
      _ct.value = TextEditingValue(
          text: txt, selection: TextSelection.collapsed(offset: txt.length));
    }

    apply(0);
    if (total == 0) {
      setState(() => _aiRefs = refs);
      _glow.forward(from: 0.0);
      return;
    }
    // ความเร็วพิมพ์ตามความยาว (0.7–1.8 วิ)
    _rv.duration =
        Duration(milliseconds: (total * 14).clamp(700, 1800).toInt());
    void tick() =>
        apply((Curves.easeOutCubic.transform(_rv.value) * total).round());
    // ถอดตัวฟังของรอบก่อน (closure ใหม่ทุกรอบ ถอดด้วย tick ใหม่ไม่ได้
    // ตัวเก่าค้าง = เขียนข้อความรอบเก่าทับรอบใหม่ จนข้อความซ้อนซ้ำ)
    final old = _rvTick;
    if (old != null) _rv.removeListener(old);
    _rvTick = tick;
    _rv.addListener(tick);
    _rv.forward(from: 0.0).whenComplete(() {
      _rv.removeListener(tick);
      if (_rvTick == tick) _rvTick = null;
      if (!mounted || _ct.text != _rvText) return;
      _ct.hi = _rvHi;
      setState(() => _aiRefs = refs);
      _glow.forward(from: 0.0);
    });
  }

  /// AI เติมจากเคส: กำลังทำ · ข้อความก่อนเติม (ไว้ย้อนกลับ จนกว่าจะพิมพ์ต่อ)
  bool _aiBusy = false;
  String? _aiUndo;

  /// ที่มาของข้อความที่ AI เติม: (ข้อความที่เติม, ชื่อหน้า/แหล่ง) · แสดงเป็นชิปใต้ช่องพิมพ์
  List<(String, String)> _aiRefs = const [];

  /// แตะชิปที่มา = ไฮไลต์เขียวเฉพาะข้อความที่มาจากแหล่งนั้น
  void _flashSrc(String src) {
    HapticFeedback.selectionClick();
    final t = _ct.text;
    final out = <TextRange>[];
    for (final (txt, sc) in _aiRefs) {
      if (sc != src || txt.trim().isEmpty) continue;
      final at = t.indexOf(txt.trim());
      if (at >= 0) out.add(TextRange(start: at, end: at + txt.trim().length));
    }
    if (out.isEmpty) return;
    out.sort((a, b) => a.start.compareTo(b.start));
    _ct.hi = out;
    _glow.forward(from: 0.0);
  }

  /// ข้อเสนอ AI เปิดอยู่ในการ์ด (แทนช่องพิมพ์)
  bool _aiPanelOn = false;

  /// เลือกข้อเสนอแล้ว (แสดง footer บันทึกในแผง)
  bool _aiPicked = false;

  /// ระยะที่แถบหัวเลื่อนขึ้นตาม scroll ข้อเสนอ (0..ความสูงหัว)
  double _hdrOff = 0.0;
  bool get _hdrMini => false;

  Future<void> _runAi() async {
    // แบบเลือกจากข้อเสนอ: สลับการ์ดเป็นรายการข้อเสนอ (กดซ้ำ = กลับหน้าพิมพ์)
    if (_w.aiPanel != null) {
      if (_rv.isAnimating || _aiBusy) return;
      HapticFeedback.selectionClick();
      _focus.unfocus();
      if (_aiPanelOn) {
        setState(() {
          _aiPanelOn = false;
          _hdrOff = 0.0;
        });
        return;
      }
      _aiPicked = false;
      // เปิดข้อเสนอ: ปุ่มเล่นแอนิเมชันกำลังวิเคราะห์ (รอผล AI · มีผลแล้วก็เล่นสั้น ๆ) แล้วค่อยแสดง
      setState(() => _aiBusy = true);
      try {
        await Future.wait([
          if (_w.aiRun case final f?)
            f(_ct.text).timeout(const Duration(seconds: 45)),
          Future.delayed(const Duration(milliseconds: 1400)),
        ]);
      } catch (e) {
        debugPrint('ข้อเสนอ AI ไม่สำเร็จ: $e');
      }
      if (!mounted) return;
      setState(() {
        _aiBusy = false;
        _aiPanelOn = true;
        _hdrOff = 0.0;
      });
      return;
    }
    final f = _w.aiRun;
    // กำลังคิดหรือกำลังพิมพ์ลงอยู่ = ไม่รับซ้ำ (กันข้อความซ้อนสองรอบ)
    if (f == null || _aiBusy || _rv.isAnimating) return;
    HapticFeedback.selectionClick();
    if (_aiUndo != null) {
      _rv.stop();
      _glow.stop();
      _ct.hi = const [];
      setState(() {
        _ct.text = _aiUndo!;
        _aiUndo = null;
        _aiRefs = const [];
      });
      return;
    }
    // ปิดคีย์บอร์ดก่อน: iOS ส่งค่าเก่ากลับมาระหว่างที่โค้ดเขียนข้อความทีละช่วง
    // (ทำให้ข้อความซ้อนซ้ำ และล้างสถานะย้อนกลับ) · แตะกล่องเพื่อพิมพ์ต่อเอง
    _focus.unfocus();
    final before = _ct.text;
    setState(() => _aiBusy = true);
    _FtAiOut? v;
    try {
      // กันค้าง: AI ไม่ตอบใน 45 วิ = ยกเลิก ปุ่มกลับมากดได้
      v = await f(before).timeout(const Duration(seconds: 45));
    } catch (e) {
      debugPrint('กรอกอัตโนมัติไม่สำเร็จ: $e');
      v = null;
    }
    if (!mounted) return;
    setState(() {
      _aiBusy = false;
      final t = v?.text.trim() ?? '';
      if (t.isNotEmpty && t != before.trim()) {
        // ไม่มีสถานะย้อนกลับ: ปุ่มคงเป็น "กรอกอัตโนมัติ" กดซ้ำ = กรอกใหม่จากข้อความปัจจุบัน
        _playFill(before, t, v!.refs);
      }
    });
  }

  // ตัวอักษรแบบเดียวกับ _t ของแอป (State นี้อยู่นอก _ErFlowHomeWidgetState)
  TextStyle _t(double size,
          {Color color = _ink, FontWeight weight = FontWeight.w500}) =>
      TextStyle(
          fontFamily: _fontFam,
          fontFamilyFallback: _fontFb,
          fontSize: size * _txtScale,
          color: color,
          fontWeight: _minW(weight),
          height: _fontLineH,
          leadingDistribution: TextLeadingDistribution.even);

  void _add(String t) {
    HapticFeedback.selectionClick();
    final cur = _ct.text.trimRight();
    _ct.text = cur.isEmpty ? t : '$cur $t';
    _ct.selection = TextSelection.collapsed(offset: _ct.text.length);
    setState(() {});
  }

  Future<void> _send() async {
    HapticFeedback.lightImpact();
    final v = _ct.text.trim();
    // เคยกรอกไว้แล้วลบจนว่าง = ลบข้อมูล ต้องยืนยันก่อน (ยกเลิก + ปุ่มแดง)
    if (v.isEmpty && _w.initial.trim().isNotEmpty) {
      _focus.unfocus();
      // bottom sheet ยืนยัน (แผ่นกลางของ ER ผ่าน _wfConfirmDelete ที่แผง workflow ตั้งไว้)
      final ok =
          await (_wfConfirmDelete?.call(_w.title) ?? Future.value(false));
      if (!ok || !mounted) return;
    }
    _wfTextClose(v);
  }

  bool get _canDelete => _w.initial.trim().isNotEmpty && !_aiPanelOn;

  /// ปุ่มลบท้ายเนื้อหา: tonal แดงจาง เต็มกว้าง แบบเดียวกับ "ลบรายการนี้" ในหน้าแก้รายการอื่น
  Widget _deleteBtn() => Padding(
        padding: const EdgeInsets.only(top: 12.0),
        child: TextButton.icon(
          onPressed: _delete,
          style: TextButton.styleFrom(
            foregroundColor: _red,
            backgroundColor: _red.withValues(alpha: 0.08),
            shape: RoundedRectangleBorder(
                borderRadius: BorderRadius.circular(16.0)),
            minimumSize: const Size(0.0, 48.0),
            padding: const EdgeInsets.symmetric(horizontal: 20.0),
          ),
          icon: const Icon(Icons.delete_outline_rounded, size: 20.0),
          label: Text('ลบรายการนี้',
              style: _t(14.0, color: _red, weight: FontWeight.w600)),
        ),
      );

  /// ปุ่มลบในหัวหน้า (แก้รายการเดิม): ยืนยันก่อน (ยกเลิก + ปุ่มแดง) แล้วบันทึกเป็นว่าง = ลบรายการ
  Future<void> _delete() async {
    HapticFeedback.selectionClick();
    _focus.unfocus();
    final ok = await (_wfConfirmDelete?.call(_w.title) ?? Future.value(false));
    if (!ok || !mounted) return;
    _wfTextClose('');
  }

  @override
  void initState() {
    super.initState();
    // สร้าง controller ตั้งแต่เริ่ม (late ที่ถูกเรียกครั้งแรกใน dispose = สร้าง ticker ตอน tree ไม่เสถียร)
    _rv;
    _wfTextValue = () => _ct.text;
    _ftAppendLine = (l) {
      if (!mounted) return;
      // ว่าง = วาดใหม่อย่างเดียว (เพิ่มแค่รหัส)
      if (l.isNotEmpty) {
        final cur = _ct.text.trimRight();
        _ct.text = cur.isEmpty ? l : '$cur\n$l';
        _ct.selection = TextSelection.collapsed(offset: _ct.text.length);
      }
      setState(() {});
    };
    _ftCommit = _wfTextCommit;
    _sp.addListener(() {
      if (!mounted) return;
      if (_sp.state == ErSpeechState.success && _sp.transcript.isNotEmpty) {
        final t = _sp.transcript;
        _sp.transcript = '';
        _add(t);
      } else {
        setState(() {});
      }
    });
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (mounted) _focus.requestFocus();
    });
  }

  @override
  void dispose() {
    if (_wfTextValue != null) _wfTextValue = null;
    _ftAppendLine = null;
    _sp.dispose();
    _rv.dispose();
    _glow.dispose();
    _focus.dispose();
    _ct.dispose();
    super.dispose();
  }

  /// ชิปที่มา (ภาษาเดียวกับ AI Overview): ไอคอนหน้า + ชื่อหน้า (ไม่มีตัวเลข)
  Widget _srcChip(String src, int n) => Material(
        color: _panel,
        shape: const StadiumBorder(
            side: BorderSide(color: Color(0xFFDADCE0), width: 0.5)),
        child: InkWell(
          customBorder: const StadiumBorder(),
          onTap: () => _flashSrc(src),
          child: Container(
            height: 30.0,
            padding: const EdgeInsets.symmetric(horizontal: 10.0),
            child: Row(mainAxisSize: MainAxisSize.min, children: [
              Icon(_ftSrcIcon(src), size: 15.0, color: _ink2),
              const SizedBox(width: 5.0),
              Text(src, style: _t(11.5, color: _ink2, weight: FontWeight.w600)),
            ]),
          ),
        ),
      );

  /// ปุ่ม AI เติมจากเคส (มุมขวาหัวแผ่น): กำลังเติม = วงหมุน · เติมแล้ว = ย้อนกลับได้
  Widget _aiPill() {
    final undo = _aiUndo != null && !_aiBusy;
    final key = _aiBusy ? 'busy' : (undo ? 'undo' : 'idle');
    // สลับสถานะต่อเนื่อง: ความกว้างปุ่มไหล (AnimatedSize) · ไอคอนจาง+ย่อขยายข้ามกัน · ข้อความเลื่อนขึ้นแทนที่
    Widget sw(Widget child, {bool slide = false}) => AnimatedSwitcher(
          duration: const Duration(milliseconds: 280),
          switchInCurve: Curves.easeOutCubic,
          switchOutCurve: Curves.easeInCubic,
          layoutBuilder: (cur, prev) => Stack(
              alignment: Alignment.centerLeft,
              children: [...prev, if (cur != null) cur]),
          transitionBuilder: (c, a) => FadeTransition(
            opacity: a,
            child: slide
                ? SlideTransition(
                    position:
                        Tween(begin: const Offset(0.0, 0.5), end: Offset.zero)
                            .animate(a),
                    child: c)
                : ScaleTransition(
                    scale: Tween(begin: 0.6, end: 1.0).animate(a), child: c),
          ),
          child: child,
        );
    // ชวนกด: ขอบไล่สี AI บาง (ไม่มีเงาฟุ้ง) · กดแล้วยุบ (_Press) · ย้อนกลับ = ขอบเทาเรียบ
    final ai = !undo;
    return _Press(
        child: AnimatedContainer(
            duration: const Duration(milliseconds: 280),
            curve: Curves.easeOutCubic,
            padding: const EdgeInsets.all(1.2),
            decoration: BoxDecoration(
              borderRadius: BorderRadius.circular(100.0),
              gradient: ai
                  ? const LinearGradient(colors: [
                      Color(0xFF4285F4),
                      Color(0xFF9B72CB),
                      Color(0xFFD96570),
                    ])
                  : const LinearGradient(
                      colors: [Color(0xFFDADCE0), Color(0xFFDADCE0)]),
            ),
            child: Material(
              color: _panel,
              shape: const StadiumBorder(),
              clipBehavior: Clip.antiAlias,
              child: InkWell(
                customBorder: const StadiumBorder(),
                onTap: _aiBusy ? null : _runAi,
                child: Padding(
                  padding: const EdgeInsets.symmetric(
                      horizontal: 16.0, vertical: 10.0),
                  child: AnimatedSize(
                    duration: const Duration(milliseconds: 320),
                    curve: Curves.easeOutCubic,
                    alignment: Alignment.centerLeft,
                    child: Row(mainAxisSize: MainAxisSize.min, children: [
                      // ต่อเนื่อง: ✦ อยู่ที่เดิมตลอด (เปลี่ยนเป็น ↺ ตอนย้อนกลับเท่านั้น)
                      // กำลังกรอก = ไอคอนแหล่งข้อมูลไหลออกจากหลัง ✦ ไปทางขวา ปุ่มยืดตามนุ่ม ๆ
                      // กำลังกรอก = ✦ ย่อจางหาย ไอคอนแหล่งข้อมูลขึ้นแทนที่ตรงนั้น (ปุ่มไม่มีไอคอนซ้อนสองชุด)
                      AnimatedSize(
                        duration: const Duration(milliseconds: 320),
                        curve: Curves.easeOutCubic,
                        alignment: Alignment.centerLeft,
                        child: AnimatedOpacity(
                          duration: const Duration(milliseconds: 200),
                          opacity: _aiBusy ? 0.0 : 1.0,
                          child: _aiBusy
                              ? const SizedBox(width: 0.0, height: 26.0)
                              : sw(KeyedSubtree(
                                  key: ValueKey(undo ? 'iu' : 'iai'),
                                  child: undo
                                      ? const Icon(Icons.undo_rounded,
                                          size: 18.0, color: _blue)
                                      // ไอคอน AI ไล่สี (ชุดเดียวกับการ์ด AI ในหน้าคำสั่ง)
                                      : ShaderMask(
                                          blendMode: BlendMode.srcIn,
                                          shaderCallback: (r) =>
                                              const LinearGradient(
                                            begin: Alignment.topLeft,
                                            end: Alignment.bottomRight,
                                            colors: [
                                              Color(0xFF4285F4),
                                              Color(0xFF9B72CB),
                                              Color(0xFFD96570),
                                            ],
                                          ).createShader(r),
                                          child: const Icon(
                                              Icons.auto_awesome_rounded,
                                              size: 19.0),
                                        ),
                                )),
                        ),
                      ),
                      AnimatedSize(
                        duration: const Duration(milliseconds: 320),
                        curve: Curves.easeOutCubic,
                        alignment: Alignment.centerLeft,
                        child: _aiBusy
                            ? TweenAnimationBuilder<double>(
                                tween: Tween(begin: 0.0, end: 1.0),
                                duration: const Duration(milliseconds: 320),
                                curve: Curves.easeOutCubic,
                                builder: (_, a, child) => Opacity(
                                  opacity: a,
                                  child: Transform.translate(
                                      offset: Offset(-16.0 * (1.0 - a), 0.0),
                                      child: child),
                                ),
                                child: const Padding(
                                  padding: EdgeInsets.zero,
                                  child: _AovSources(icons: [
                                    Icons.person_outline_rounded,
                                    Icons.chat_bubble_outline_rounded,
                                    Icons.monitor_heart_outlined,
                                  ], loading: true, ink: _blue, wave: true),
                                ),
                              )
                            : const SizedBox(height: 26.0),
                      ),
                      // กำลังกรอก = ไม่มีข้อความ ไอคอนแหล่งข้อมูลวนเด้งบอกสถานะเอง
                      // ข้อความหดหายไปพร้อมปุ่มที่แคบลงเป็นแคปซูลไอคอน
                      AnimatedSize(
                        duration: const Duration(milliseconds: 320),
                        curve: Curves.easeOutCubic,
                        alignment: Alignment.centerLeft,
                        child: AnimatedOpacity(
                          duration: const Duration(milliseconds: 160),
                          opacity: _aiBusy ? 0.0 : 1.0,
                          child: _aiBusy
                              ? const SizedBox(width: 0.0)
                              : Padding(
                                  padding: const EdgeInsets.only(left: 8.0),
                                  child: sw(
                                      Text(
                                          key: ValueKey('t$key'),
                                          undo
                                              ? 'ย้อนกลับ'
                                              : (_w.aiLabel ?? 'กรอกอัตโนมัติ'),
                                          style: _t(13.0,
                                              color: _inkTitle,
                                              weight: FontWeight.w600)),
                                      slide: true),
                                ),
                        ),
                      ),
                    ]),
                  ),
                ),
              ),
            )));
  }

  /// แถวชิปที่มา: ป้าย "แหล่งที่มา" ชิดซ้าย + ชิปเลื่อนแนวนอน (ขอบขวาจาง)
  /// ชิปทยอยไหลออกทีละอันจากซ้ายไปขวา (ต่อจากไอคอนซ้อนตอนวิเคราะห์)
  Widget _srcRow() {
    final srcs = [for (final x in _aiRefs) x.$2].toSet().toList();
    return Padding(
      key: ValueKey(srcs.join('|')),
      padding: const EdgeInsets.only(top: 10.0),
      child: Row(children: [
        // ป้ายแหล่งที่มาชิดซ้าย แล้วชิปเรียงต่อไปทางขวา (เลื่อนได้)
        Padding(
          padding: const EdgeInsets.only(left: 4.0, right: 8.0),
          child: Text('แหล่งที่มา',
              style: _t(12.0, color: _ink3, weight: FontWeight.w500)),
        ),
        Expanded(
          child: SizedBox(
            height: 30.0,
            child: ShaderMask(
              blendMode: BlendMode.dstIn,
              shaderCallback: (r) => const LinearGradient(
                begin: Alignment.centerLeft,
                end: Alignment.centerRight,
                stops: [0.0, 0.9, 1.0],
                colors: [
                  Color(0xFFFFFFFF),
                  Color(0xFFFFFFFF),
                  Color(0x00FFFFFF)
                ],
              ).createShader(r),
              child: ListView.separated(
                scrollDirection: Axis.horizontal,
                padding: const EdgeInsets.only(left: 2.0, right: 20.0),
                itemCount: srcs.length,
                separatorBuilder: (_, __) => const SizedBox(width: 6.0),
                itemBuilder: (_, i) => TweenAnimationBuilder<double>(
                  tween: Tween(begin: 0.0, end: 1.0),
                  duration: Duration(milliseconds: 320 + 90 * i),
                  curve: Interval((90 * i) / (320 + 90 * i), 1.0,
                      curve: Curves.easeOutCubic),
                  builder: (_, a, child) => Opacity(
                    opacity: a,
                    child: Transform.translate(
                        offset: Offset(-14.0 * (1.0 - a), 0.0), child: child),
                  ),
                  child: _srcChip(
                      srcs[i], _aiRefs.where((x) => x.$2 == srcs[i]).length),
                ),
              ),
            ),
          ),
        ),
      ]),
    );
  }

  @override
  Widget build(BuildContext context) {
    return Padding(
      // nested card: กล่องพิมพ์ห่างขอบ 16 · หัวเยื้องเข้าอีก 8
      padding: const EdgeInsets.fromLTRB(16.0, 6.0, 16.0, 10.0),
      child: Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
        // แถบหัว (ชื่อ + ปุ่ม AI): หน้าพิมพ์ = อยู่กับที่ · แผงข้อเสนอ AI = เลื่อนไปกับรายการ (sliver)
        // มีส่วนเสริม (ICD-10) = หัวลอยแล้วหดตาม scroll เหมือนแผงข้อเสนอ AI
        if (!(_aiPanelOn && _w.aiPanel != null) && _w.extra == null)
          _ftHeader(),
        // ข้อเสนอ AI: ชิดหัวขึ้น (ป้าย Most likely คร่อมขอบบนการ์ดเว้นที่ให้แล้ว)
        SizedBox(
            height: (_aiPanelOn && _w.aiPanel != null) || _w.extra != null
                ? 0.0
                : 12.0),
        // กำลังเลือกข้อเสนอ AI: ไม่มี footer (เลือกในแผงแล้วกลับหน้าพิมพ์เอง) · เนื้อหาเต็มลงถึงขอบล่าง
        // ข้อเสนอ AI: เลือกแล้ว footer ลอยขึ้นจากล่าง (หลัก footer: ปุ่มลอย ไม่มีพื้นรอง)
        // เนื้อหาเว้นที่ให้ footer · ยังไม่เลือก = ไม่มี footer
        if (_aiPanelOn && _w.aiPanel != null)
          Expanded(
            child: Stack(children: [
              Positioned.fill(
                // หลัก footer: เนื้อหาเต็มถึงขอบล่าง ไหลลอดใต้ปุ่มที่ลอยอยู่ (จางช่วงท้าย)
                child: ShaderMask(
                  blendMode: BlendMode.dstIn,
                  shaderCallback: (r) {
                    double at(double px) =>
                        ((r.height - px) / r.height).clamp(0.0, 1.0);
                    return LinearGradient(
                      begin: Alignment.topCenter,
                      end: Alignment.bottomCenter,
                      colors: true
                          ? [
                              Colors.white,
                              Colors.white,
                              Colors.white.withValues(alpha: 0.0)
                            ]
                          : const [Colors.white, Colors.white, Colors.white],
                      stops: [0.0, at(110.0), at(40.0)],
                    ).createShader(r);
                  },
                  // เลื่อนรายการข้อเสนอ = หดหัว (กลับบนสุด = กางคืน)
                  child: NotificationListener<ScrollUpdateNotification>(
                    onNotification: (n) {
                      if (n.metrics.axis != Axis.vertical) return false;
                      final o = n.metrics.pixels.clamp(0.0, _ftHdrH);
                      if ((o - _hdrOff).abs() > 0.5)
                        setState(() => _hdrOff = o);
                      return false;
                    },
                    child: _ftCard(),
                  ),
                ),
              ),
              Positioned(
                left: 0.0,
                right: 0.0,
                bottom: 0.0,
                // footer แสดงตลอด · ยังไม่เลือกโรค = ปุ่มบันทึกกดไม่ได้
                child: _ftFooter(
                    mic: false,
                    canSave: _aiPicked,
                    // ย้อนกลับจากหน้าข้อเสนอที่เลือกไว้แล้ว = เตือนว่ายังไม่ถูกบันทึก
                    onBack: () async {
                      if (_aiPicked &&
                          !await (_wfConfirmReplaceAi?.call(_w.title) ??
                              Future.value(true))) {
                        return;
                      }
                      _wfTextClose(null);
                    },
                    onMain: () {
                      HapticFeedback.selectionClick();
                      setState(() {
                        _aiPanelOn = false;
                        _hdrOff = 0.0;
                        // กลับมาพร้อมค่าที่เลือก = เนื้อหาไล่โผล่ (appear)
                        _dxAppearTick++;
                      });
                    }),
              ),
              // หัวลอยเหนือรายการ เลื่อนขึ้นเท่าระยะ scroll (เหมือนอยู่ในรายการเดียวกัน) แล้วจาง
              Positioned(
                left: 0.0,
                right: 0.0,
                top: -_hdrOff,
                child: IgnorePointer(
                  ignoring: _hdrOff > 20.0,
                  // เลื่อนเท่าระยะ scroll พอดี = ไปกับรายการ (ไม่จาง ไม่มีพื้นทับเนื้อหา)
                  child: _ftHeader(),
                ),
              ),
            ]),
          )
        else ...[
          // มีส่วนเสริม (รหัส ICD-10): ช่องพิมพ์สูงพอดีข้อความ + การ์ดรหัสแยกใต้ เลื่อนรวมกัน
          // ไม่มี = ช่องพิมพ์เต็มความสูงแบบเดิม
          // มีส่วนเสริม (รหัส ICD-10): การ์ดเดียว = หัว "ลงบันทึกคำวินิจฉัย" · ข้อความ · เส้น · แถวรหัส
          // หลัก footer: เนื้อหาเลื่อนลอดใต้ปุ่มลอย (จางช่วงท้าย) · เผื่อท้ายให้รายการสุดท้ายพ้นปุ่ม
          if (_w.extra case final ex?)
            Expanded(
              child: Stack(children: [
                Positioned.fill(
                  child: ShaderMask(
                    blendMode: BlendMode.dstIn,
                    shaderCallback: (r) {
                      double at(double px) =>
                          ((r.height - px) / r.height).clamp(0.0, 1.0);
                      return LinearGradient(
                        begin: Alignment.topCenter,
                        end: Alignment.bottomCenter,
                        // บน: จางสั้น ๆ ใต้ breadcrumb ตอนเนื้อหาเลื่อนขึ้น (ไม่ตัดขอบแข็ง)
                        colors: [
                          Colors.white.withValues(alpha: 0.0),
                          Colors.white,
                          Colors.white,
                          Colors.white.withValues(alpha: 0.0),
                        ],
                        stops: [0.0, 18.0 / r.height, at(110.0), at(40.0)],
                      ).createShader(r);
                    },
                    // เลื่อนลง = หัว (ชื่อ + ปุ่ม AI) เลื่อนออกไปกับเนื้อหา · กลับบนสุด = กางคืน
                    child: NotificationListener<ScrollUpdateNotification>(
                      onNotification: (n) {
                        if (n.metrics.axis != Axis.vertical) return false;
                        final o = n.metrics.pixels.clamp(0.0, _ftHdrH + 12.0);
                        if ((o - _hdrOff).abs() > 0.5) {
                          setState(() => _hdrOff = o);
                        }
                        return false;
                      },
                      child: ListView(
                          padding: const EdgeInsets.only(
                              top: _ftHdrH + 12.0, bottom: 84.0),
                          children: [
                            // หลัก nested card: การ์ดนอกขอบใน 8 · หัวข้อเยื้อง 16 · การ์ดในขาว + เส้น 0.5
                            Container(
                              padding: const EdgeInsets.fromLTRB(
                                  8.0, 14.0, 8.0, 12.0),
                              decoration: BoxDecoration(
                                color: _panel,
                                borderRadius: BorderRadius.circular(16.0),
                                border: Border.all(
                                    color: const Color(0xFFDADCE0), width: 0.5),
                              ),
                              child: Column(
                                  crossAxisAlignment:
                                      CrossAxisAlignment.stretch,
                                  children: [
                                    // หัวการ์ด + ปุ่มลบขวา (แก้รายการเดิม) · สูงคงที่ มี/ไม่มีปุ่มเท่ากัน
                                    SizedBox(
                                      height: 36.0,
                                      child: Row(children: [
                                        Expanded(
                                          child: Padding(
                                            padding: const EdgeInsets.only(
                                                left: 8.0),
                                            child: Text('ลงบันทึกคำวินิจฉัย',
                                                style: _t(15.0,
                                                    color: _inkTitle,
                                                    weight: FontWeight.w700)),
                                          ),
                                        ),
                                      ]),
                                    ),
                                    const SizedBox(height: 4.0),
                                    // ข้อความ = nested card พื้น surface เทาจาง ไม่มีเส้นขอบ
                                    // กลับจากข้อเสนอ AI = โผล่ไล่ลำดับ (ข้อความ → ICD-10 → แถวรหัส)
                                    _Appear(
                                      key: ValueKey('ft-text-$_dxAppearTick'),
                                      index: 0,
                                      child: Container(
                                        constraints: const BoxConstraints(
                                            minHeight: 76.0),
                                        padding: const EdgeInsets.fromLTRB(
                                            14.0, 12.0, 14.0, 12.0),
                                        decoration: BoxDecoration(
                                          color: const Color(0xFFF8F9FA),
                                          borderRadius:
                                              BorderRadius.circular(12.0),
                                        ),
                                        child: TextField(
                                          controller: _ct,
                                          focusNode: _focus,
                                          minLines: 2,
                                          maxLines: 8,
                                          cursorColor: _blue,
                                          keyboardType: TextInputType.multiline,
                                          onChanged: (_) =>
                                              setState(() => _ct.hi = const []),
                                          style: _t(15.0,
                                              color: _ink2,
                                              weight: FontWeight.w500),
                                          decoration: InputDecoration(
                                            isDense: true,
                                            border: InputBorder.none,
                                            contentPadding: EdgeInsets.zero,
                                            hintText: _w.hint,
                                            hintStyle: _t(15.0,
                                                color: _g5,
                                                weight: FontWeight.w500),
                                          ),
                                        ),
                                      ),
                                    ),
                                    const SizedBox(height: 14.0),
                                    _Appear(
                                      key: ValueKey('ft-icd-$_dxAppearTick'),
                                      index: 1,
                                      // การ์ดรหัส = การ์ดใน (ขอบใน 8 เท่าช่องพิมพ์) · หัวข้อเยื้อง 16 อยู่ใน ex
                                      child: ex(() {
                                        if (mounted) setState(() {});
                                      }),
                                    ),
                                  ]),
                            ),
                            // แก้รายการเดิม = ปุ่มลบใต้การ์ด (นอกการ์ด)
                            if (_canDelete) _deleteBtn(),
                          ]),
                    ),
                  ),
                ),
                Positioned(
                    left: 0.0, right: 0.0, bottom: 0.0, child: _ftFooter()),
                Positioned(
                  left: 0.0,
                  right: 0.0,
                  top: -_hdrOff,
                  child: IgnorePointer(
                    ignoring: _hdrOff > 20.0,
                    child: _ftHeader(),
                  ),
                ),
              ]),
            )
          else
            Expanded(child: _ftCard()),
          if (_sp.state != ErSpeechState.idle &&
              _sp.state != ErSpeechState.success)
            Padding(
              padding: const EdgeInsets.only(top: 8.0, left: 8.0),
              child: Text(_sp.message,
                  style: _t(12.0,
                      color: _sp.state == ErSpeechState.listening ||
                              _sp.state == ErSpeechState.processing
                          ? _ink3
                          : _red,
                      weight: FontWeight.w500)),
            ),
          if (_w.extra == null) ...[
            const SizedBox(height: 14.0),
            _ftFooter(),
          ],
        ],
      ]),
    );
  }

  Widget _ftHeader() => Padding(
        padding: const EdgeInsets.only(left: 8.0),
        child: Row(children: [
          Expanded(
            child:
                Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
              // เลื่อนดูข้อเสนอ = หัวหดลง (ชื่อเล็กลง ซ่อนบรรทัดรอง)
              AnimatedDefaultTextStyle(
                duration: const Duration(milliseconds: 200),
                curve: Curves.easeOut,
                style: _t(17.0, color: _inkTitle, weight: FontWeight.w700),
                child: Text(_w.title),
              ),
              if (_w.sub != null)
                AnimatedSize(
                  duration: const Duration(milliseconds: 200),
                  curve: Curves.easeOut,
                  alignment: Alignment.topLeft,
                  child: _hdrMini
                      ? const SizedBox(width: double.infinity)
                      : Text(_w.sub!,
                          maxLines: 1,
                          overflow: TextOverflow.ellipsis,
                          style:
                              _t(12.5, color: _ink3, weight: FontWeight.w500)),
                ),
            ]),
          ),
          if (_w.aiRun != null) ...[
            const SizedBox(width: 8.0),
            // ระหว่างเลือกข้อเสนอ = ปิดปุ่ม AI (ออกด้วย ← ใน footer)
            IgnorePointer(
              ignoring: _aiPanelOn,
              child: AnimatedOpacity(
                duration: const Duration(milliseconds: 200),
                opacity: _aiPanelOn ? 0.4 : 1.0,
                child: _aiPill(),
              ),
            ),
          ],
        ]),
      );

  Widget _ftCard() => Container(
        clipBehavior: Clip.antiAlias,
        decoration: BoxDecoration(
          color: _panel,
          borderRadius: BorderRadius.circular(14.0),
          // ข้อเสนอ AI เปิดอยู่ = ไม่มีเส้นกรอบ (เนื้อหาวางบนแผงตรง ๆ)
          border: Border.all(
              color: _aiPanelOn && _w.aiPanel != null
                  ? const Color(0x00DADCE0)
                  : const Color(0xFFDADCE0),
              width: 0.5),
        ),
        // ข้อเสนอ AI แบบเลือก: แทนที่เนื้อหาการ์ด (จางสลับ) · เลือกแล้วกลับเป็นช่องพิมพ์ + เติมเขียว
        child: AnimatedSwitcher(
          duration: const Duration(milliseconds: 260),
          // ชิดบนเสมอ (ค่าเริ่มของ AnimatedSwitcher = กลาง เนื้อหาสั้นจะลอยกลางการ์ด)
          layoutBuilder: (cur, prev) => Stack(
              alignment: Alignment.topCenter,
              children: [...prev, if (cur != null) cur]),
          child: _aiPanelOn && _w.aiPanel != null
              ? KeyedSubtree(
                  key: const ValueKey('ai-panel'),
                  child: _w.aiPanel!((out) {
                    // เลือกแล้วยังอยู่ในแผง: ลงข้อความ + ที่มาไว้ แล้วโชว์ footer ให้บันทึก
                    if (!mounted) return;
                    final t = out?.text.trim() ?? '';
                    setState(() {
                      _ct.hi = const [];
                      _ct.text = t;
                      _aiRefs = out?.refs ?? const [];
                      // เอาออกหมด = ซ่อน footer
                      _aiPicked = t.isNotEmpty;
                    });
                  }))
              : KeyedSubtree(
                  key: const ValueKey('ai-text'),
                  child: Column(children: [
                    Expanded(
                        child: Stack(children: [
                      Positioned.fill(
                        child: Padding(
                          // ข้อความเต็มความสูงการ์ด เลื่อนลอดใต้แถบแหล่งที่มา
                          padding:
                              const EdgeInsets.fromLTRB(12.0, 0.0, 12.0, 0.0),
                          // จางช่วงท้ายแบบ footer workflow: ข้อความใต้ชิปยังเห็นจาง ๆ (ไม่เบลอ)
                          child: ShaderMask(
                              blendMode: BlendMode.dstIn,
                              shaderCallback: (r) {
                                if (_aiRefs.isEmpty) {
                                  return const LinearGradient(
                                          colors: [Colors.white, Colors.white])
                                      .createShader(r);
                                }
                                final h = r.height;
                                double at(double px) =>
                                    (1.0 - px / h).clamp(0.0, 1.0);
                                return LinearGradient(
                                  begin: Alignment.topCenter,
                                  end: Alignment.bottomCenter,
                                  colors: [
                                    Colors.white,
                                    Colors.white,
                                    Colors.white.withValues(alpha: 0.6),
                                    Colors.white.withValues(alpha: 0.3),
                                  ],
                                  stops: [0.0, at(80.0), at(46.0), 1.0],
                                ).createShader(r);
                              },
